insert into public.products
  (id, order_num, name, short_name, short_description, target_audience, benefits, basic_conditions, key_selling_points, objection_bank, compliance_note)
values
('tiet-kiem-online', 1, 'Tiết kiệm online', null, 'Gửi tiết kiệm hoàn toàn qua app, không cần ra quầy, lãi suất ưu đãi hơn so với gửi tại quầy.', 'Người có tiền nhàn rỗi, ưu tiên an toàn, ít chấp nhận rủi ro.', '["Lãi suất ưu đãi hơn 0.1–0.3%/năm so với gửi tại quầy","Kỳ hạn linh hoạt (1–36 tháng)","Tất toán trước hạn vẫn được hưởng lãi không kỳ hạn cho phần đã gửi đủ","Thao tác 100% trên app, không cần ra chi nhánh"]'::jsonb, 'Có tài khoản thanh toán MSB, số tiền gửi tối thiểu 1.000.000đ', '["Lãi suất cao hơn tại quầy","An toàn tuyệt đối, được bảo hiểm tiền gửi theo quy định NHNN","Linh hoạt kỳ hạn, rút trước hạn không mất hết lãi","Thao tác nhanh, không cần ra chi nhánh"]'::jsonb, '[{"question":"Gửi online có an toàn không, lỡ mất tiền thì sao?","sampleAnswer":"Gửi online an toàn tương đương tại quầy, tiền gửi được bảo hiểm theo quy định của Nhà nước, sổ tiết kiệm điện tử có giá trị pháp lý như sổ giấy."},{"question":"Lãi suất online cao hơn tại quầy thật không hay chỉ quảng cáo?","sampleAnswer":"Đây là chính sách chính thức của ngân hàng — có thể xem trực tiếp bảng lãi suất trong app, minh bạch và cập nhật theo thời gian thực."},{"question":"Tôi cần tiền gấp thì rút giữa chừng có bị mất hết lãi không?","sampleAnswer":"Không mất hết — phần tiền gửi đủ kỳ hạn tối thiểu vẫn được tính lãi không kỳ hạn, không bị mất trắng như trước đây."},{"question":"Thao tác trên app tôi không rành công nghệ.","sampleAnswer":"Thao tác chỉ 3 bước đơn giản, có hướng dẫn từng bước trong app, và luôn có tổng đài/nhân viên hỗ trợ nếu cần."}]'::jsonb, null),
('the-tin-dung', 2, 'Thẻ tín dụng', null, 'Thẻ tín dụng quốc tế, chi tiêu trước – trả tiền sau, kèm ưu đãi hoàn tiền/tích điểm.', 'Người có thu nhập ổn định, thường xuyên chi tiêu online/mua sắm, hay đi công tác/du lịch.', '["Miễn lãi tới 45–55 ngày","Hoàn tiền theo danh mục chi tiêu (ăn uống, mua sắm online, xăng dầu...)","Miễn phí thường niên năm đầu","Tích điểm đổi quà/dặm bay"]'::jsonb, 'Đủ 18 tuổi, chứng minh được thu nhập (lương chuyển khoản hoặc hợp đồng lao động)', '["Miễn lãi tới 45–55 ngày","Hoàn tiền/tích điểm theo thói quen chi tiêu","Miễn phí thường niên năm đầu","Mở thẻ nhanh, duyệt qua app"]'::jsonb, '[{"question":"Dùng thẻ tín dụng dễ nợ nần, tôi sợ không kiểm soát được.","sampleAnswer":"App có công cụ theo dõi chi tiêu theo thời gian thực, có thể tự đặt hạn mức cảnh báo, hạn mức thẻ cũng được cấp dựa trên thu nhập nên không vượt khả năng chi trả."},{"question":"Phí thường niên có đắt không?","sampleAnswer":"Miễn phí hoàn toàn năm đầu, các năm sau có thể tiếp tục được miễn nếu đạt doanh số chi tiêu tối thiểu theo chính sách."},{"question":"Tôi đã có thẻ ngân hàng khác rồi.","sampleAnswer":"Vậy anh/chị đang thấy thẻ hiện tại còn thiếu ưu đãi gì? (khai thác nhu cầu) — sau đó so sánh điểm khác biệt về hoàn tiền/tích điểm."},{"question":"Thủ tục mở thẻ có phức tạp không?","sampleAnswer":"Hoàn toàn qua app, hồ sơ đơn giản, thời gian duyệt chỉ vài phút."}]'::jsonb, null),
('vay-tieu-dung', 3, 'Vay tiêu dùng', null, 'Vay tín chấp phục vụ nhu cầu tiêu dùng cá nhân (sửa nhà, mua sắm, y tế, du lịch...), không cần tài sản đảm bảo.', 'Người có nhu cầu tài chính ngắn–trung hạn, thu nhập ổn định.', '["Giải ngân nhanh, có thể trong ngày","Không cần tài sản thế chấp","Lãi suất cạnh tranh","Trả góp linh hoạt theo tháng"]'::jsonb, 'Chứng minh thu nhập, độ tuổi 20–60, lịch sử tín dụng tốt (không nợ xấu)', '["Giải ngân nhanh, không cần thế chấp","Lãi suất cạnh tranh, minh bạch","Kỳ hạn và số tiền vay linh hoạt theo nhu cầu","Hồ sơ đơn giản, xét duyệt online"]'::jsonb, '[{"question":"Lãi suất vay tiêu dùng thường cao lắm.","sampleAnswer":"Mức lãi suất cụ thể phụ thuộc hồ sơ từng người, nhưng vẫn thấp hơn nhiều so với vay nóng bên ngoài, và hoàn toàn minh bạch ngay từ đầu."},{"question":"Tôi sợ không trả nợ đúng hạn.","sampleAnswer":"Có thể cùng tính toán số tiền trả góp phù hợp với thu nhập trước khi quyết định vay, chọn kỳ hạn sao cho khoản trả hàng tháng thoải mái nhất."},{"question":"Thủ tục vay có phức tạp, mất nhiều thời gian không?","sampleAnswer":"Hồ sơ đơn giản, xét duyệt hoàn toàn online, có thể giải ngân ngay trong ngày nếu hồ sơ đầy đủ."},{"question":"Tôi chưa có nhu cầu vay ngay bây giờ.","sampleAnswer":"Không sao, có thể giữ liên hệ và giới thiệu một hạn mức vay dự phòng sẵn có, khi nào cần chỉ cần thao tác trên app."}]'::jsonb, null),
('bao-hiem-lien-ket', 4, 'Bảo hiểm liên kết', null, 'Sản phẩm bảo hiểm nhân thọ liên kết đầu tư — kết hợp bảo vệ tài chính trước rủi ro và tích lũy dài hạn.', 'Người có thu nhập ổn định, mong muốn bảo vệ tài chính cho bản thân/gia đình kết hợp tích lũy dài hạn.', '["Bảo vệ trước rủi ro (bệnh hiểm nghèo, tai nạn, tử vong)","Giá trị tài khoản tích lũy tăng theo thời gian","Có thể rút một phần giá trị khi cần"]'::jsonb, 'Đóng phí định kỳ (năm/quý/tháng), thời hạn hợp đồng dài hạn (10–20 năm)', '["Vừa bảo vệ vừa tích lũy — 2 trong 1","Linh hoạt chọn mức rủi ro của phần đầu tư","Có quyền cân nhắc/hủy trong 21 ngày đầu (thời gian cân nhắc)","Phí thấp hơn nếu tham gia sớm"]'::jsonb, '[{"question":"Bảo hiểm liên kết đầu tư có rủi ro mất tiền không?","sampleAnswer":"Sản phẩm gồm 2 phần rõ ràng: phần bảo vệ cố định và phần đầu tư có nhiều mức rủi ro để lựa chọn — mọi thông tin đều được công khai minh bạch trong hợp đồng và minh họa quyền lợi."},{"question":"Tôi từng nghe nhiều người bị tư vấn sai, đóng xong không rút được.","sampleAnswer":"Rất hiểu lo lắng này — chúng ta sẽ cùng đọc kỹ từng điều khoản trước khi ký, và anh/chị có 21 ngày cân nhắc sau khi ký để xem xét lại, hoàn toàn chủ động."},{"question":"Phí đóng hàng năm cao quá, tôi không đủ khả năng.","sampleAnswer":"Có thể điều chỉnh mức phí phù hợp với thu nhập hiện tại, không nhất thiết phải chọn gói cao nhất ngay từ đầu."},{"question":"Tôi còn trẻ, chưa cần bảo hiểm.","sampleAnswer":"Tham gia càng sớm, mức phí càng thấp và thời gian tích lũy càng dài — đây chính là thời điểm tối ưu nhất để bắt đầu."}]'::jsonb, 'BẮT BUỘC phải nói rõ đây là sản phẩm có yếu tố đầu tư (không cam kết lợi nhuận cố định) và nhắc khách hàng về quyền cân nhắc 21 ngày. Đây là 1 tiêu chí trong checklist "Tuân thủ quy trình" ở phần chấm điểm.'),
('combo', 5, 'Combo (Tài khoản số + Bảo hiểm + Đầu tư)', 'Combo', 'Gói combo tích hợp mở tài khoản số miễn phí, kèm bảo hiểm cơ bản và sản phẩm đầu tư (quỹ mở/chứng chỉ quỹ) — sản phẩm bán chéo, khó nhất trong 5 sản phẩm, đòi hỏi khai thác nhu cầu tổng thể trước khi đề xuất.', 'Khách hàng đã có quan hệ với ngân hàng, có khả năng tài chính tốt, phù hợp để bán chéo/upsell.', '["Tiết kiệm chi phí khi mua combo so với mua lẻ từng sản phẩm","Tối ưu hoá tài chính toàn diện trong 1 lần tư vấn","Ưu đãi riêng dành cho khách hàng combo"]'::jsonb, 'Thường yêu cầu số dư/thu nhập cao hơn mức trung bình, cần tư vấn kỹ nhu cầu tổng thể trước khi đề xuất.', '["Tiết kiệm chi phí tổng thể so với mua lẻ","Giải pháp tài chính toàn diện, không phải chắp vá từng phần","Có thể tuỳ chỉnh từng phần trong combo theo nhu cầu thật","Ưu đãi độc quyền cho khách combo"]'::jsonb, '[{"question":"Tôi chỉ cần 1 sản phẩm thôi, sao phải mua combo?","sampleAnswer":"Hoàn toàn hiểu — combo không bắt buộc trọn gói, mỗi phần đều là sản phẩm độc lập hữu ích, chỉ là khi kết hợp sẽ tiết kiệm chi phí hơn đáng kể."},{"question":"Nghe combo là thấy bị ép mua thêm cái không cần.","sampleAnswer":"Không hề ép buộc — anh/chị hoàn toàn có quyền tuỳ chỉnh, bỏ bớt phần không phù hợp, mình chỉ đề xuất dựa trên đúng nhu cầu đã trao đổi."},{"question":"Tôi đã có sản phẩm đầu tư ở nơi khác rồi.","sampleAnswer":"Vậy sản phẩm hiện tại anh/chị đang hài lòng nhất ở điểm nào? (khai thác insight) — từ đó chỉ ra điểm khác biệt của combo, ví dụ liên kết trực tiếp với tài khoản đang dùng."},{"question":"Tôi cần thời gian suy nghĩ, việc này lớn quá.","sampleAnswer":"Hoàn toàn tôn trọng — có thể gửi tài liệu tham khảo chi tiết và hẹn trao đổi lại vào thời điểm anh/chị thuận tiện hơn."}]'::jsonb, 'Có yếu tố đầu tư (qua phần bảo hiểm liên kết/quỹ) — áp dụng cùng lưu ý compliance như Bảo hiểm liên kết: không cam kết lợi nhuận cố định, nhắc quyền cân nhắc nếu áp dụng.')
insert into public.personas
  (id, chapter_number, name, star_rating, criteria, behavior_note, general_tactic, win_condition, recommended_product_id, is_boss_chapter)
values
('noi-tro-tiet-kiem', 1, 'Nội trợ tiết kiệm', 1, '{"age":"38–55 tuổi","occupation":"Nội trợ, quản lý chi tiêu gia đình","incomeLevel":"Thu nhập chồng + thu nhập phụ, ổn định ở mức trung bình","needs":"Gửi tiết kiệm an toàn, sinh lời ổn định cho khoản tiền nhàn rỗi trong nhà","painPoints":"Sợ rủi ro mất tiền; không rành công nghệ tài chính, ngại thao tác app phức tạp","expectations":"Giải thích rõ ràng, chậm rãi, dùng từ ngữ đơn giản, không thuật ngữ chuyên môn","barriers":"Cần người thân/quen giới thiệu hoặc giải thích thật đơn giản mới yên tâm"}'::jsonb, 'Dễ tính, ít phản bác gay gắt, nhưng hay hỏi lại nhiều lần cho chắc, cần được trấn an về độ an toàn.', 'Nói chậm, ví dụ đời thường (so sánh với đi chợ, sổ tiết kiệm giấy...), trấn an an toàn trước khi nói lợi ích.', 'Khách đồng ý gửi tiết kiệm, hoặc ít nhất đồng ý thử thao tác app cùng nhân viên/hẹn quay lại.', 'tiet-kiem-online', false),
('nv-van-phong-tre', 2, 'Nhân viên văn phòng trẻ', 2, '{"age":"24–32 tuổi","occupation":"Nhân viên văn phòng","incomeLevel":"Thu nhập ổn định","needs":"Quản lý chi tiêu thông minh, tiện lợi, có ưu đãi khi mua sắm online","painPoints":"Không có nhiều thời gian; dễ mất kiên nhẫn nếu bị tư vấn lan man, không đúng trọng tâm","expectations":"Ngắn gọn, đúng trọng tâm, có thể thao tác hoàn tất ngay trên điện thoại trong cuộc gọi","barriers":"Đã quen dùng ví điện tử/thẻ ngân hàng khác, cần thấy lợi ích khác biệt rõ ràng ngay từ đầu"}'::jsonb, 'Hỏi nhanh, đi thẳng vào lợi ích cụ thể ("được gì?"), dễ mất kiên nhẫn nếu nhân viên vòng vo quá lâu.', 'Đi thẳng vào lợi ích, dùng số liệu/con số cụ thể, tôn trọng thời gian của khách.', 'Khách đồng ý mở sản phẩm hoặc để lại thông tin đăng ký ngay trong cuộc gọi.', 'the-tin-dung', false),
('chu-ho-kinh-doanh', 3, 'Chủ hộ kinh doanh', 3, '{"age":"35–55 tuổi","occupation":"Tự kinh doanh (tạp hoá/shop online/quán ăn...)","incomeLevel":"Thu nhập biến động theo kinh doanh, có tài sản tích luỹ","needs":"Vốn xoay vòng kinh doanh, quản lý dòng tiền hiệu quả","painPoints":"Sợ lãi suất tăng bất ngờ; sợ thủ tục phức tạp làm mất thời gian kinh doanh","expectations":"Câu trả lời cụ thể, có số liệu rõ ràng, không thích bị \"quảng cáo\" chung chung","barriers":"Đã có quan hệ tín dụng với ngân hàng khác, cần thấy lợi thế cạnh tranh cụ thể bằng số liệu"}'::jsonb, 'Đặt câu hỏi khó, hay so sánh trực tiếp với đối thủ/ngân hàng khác, cần bằng chứng thuyết phục.', 'Luôn chuẩn bị số liệu cụ thể (lãi suất, thời gian giải ngân, phí), so sánh trực diện với đối thủ nếu được hỏi.', 'Khách đồng ý cung cấp hồ sơ để xét duyệt, hoặc hẹn gặp trực tiếp bàn kỹ hơn.', 'vay-tieu-dung', false),
('nguoi-da-nghi', 4, 'Người đa nghi / từng bị lừa', 4, '{"age":"Không giới hạn cụ thể, đa số trung niên trở lên","occupation":"Đa dạng","incomeLevel":"Đa dạng, có nhu cầu tài chính thật","needs":"Bảo vệ rủi ro, tích luỹ — nhưng cần được xây dựng niềm tin trước khi mở lòng","painPoints":"Sợ bị lừa lần nữa; sợ đọc không kỹ hợp đồng rồi thiệt hại về sau; từng bị tư vấn sai, mất tiền","expectations":"Minh bạch tuyệt đối, giải thích kỹ từng điều khoản, không bị hối thúc chốt nhanh","barriers":"Niềm tin thấp với ngành tài chính nói chung, không dễ bị thuyết phục bằng lời nói suông"}'::jsonb, 'Chất vấn liên tục, có thể kể lại trải nghiệm xấu trước đó, dễ cúp máy nếu cảm thấy bị "bán" ép.', 'Minh bạch mọi điều khoản/phí ngay cả khi bất lợi, không hối thúc, thừa nhận rủi ro thay vì né tránh, kiên nhẫn lắng nghe câu chuyện cũ của khách trước khi tư vấn.', 'Khách bắt đầu cởi mở, đặt câu hỏi thật thay vì phòng thủ, hoặc đồng ý tìm hiểu thêm tài liệu — không nhất thiết phải chốt được ngay.', 'bao-hiem-lien-ket', false),
('khach-vip', 5, 'Khách VIP / đàm phán cứng', 5, '{"age":"Trung niên trở lên, thành đạt","occupation":"Doanh nhân / chuyên gia cấp cao","incomeLevel":"Tài sản/thu nhập cao","needs":"Tối ưu hoá tài chính tổng thể, dịch vụ cá nhân hoá đúng nhu cầu riêng","painPoints":"Ghét bị tư vấn kiểu đại trà, rập khuôn; không thích bị \"bán\" một cách lộ liễu","expectations":"Nhân viên phải hiểu rõ nhu cầu tổng thể trước khi đề xuất bất kỳ sản phẩm nào, không chăm chăm chốt 1 thứ","barriers":"Đã có nhiều mối quan hệ ngân hàng khác, đòi hỏi cao, khó gây ấn tượng bằng cách tư vấn thông thường"}'::jsonb, 'Kiểm soát cuộc trò chuyện, đặt câu hỏi sắc, thử thách nhân viên, không dễ bị thuyết phục nhanh.', 'Thể hiện đẳng cấp tư vấn (kiến thức sâu, số liệu chính xác), cá nhân hoá mọi đề xuất, giữ thái độ tự tin nhưng không xu nịnh.', 'Nếu bán được combo là xuất sắc; nếu chưa chốt được ngay, khai thác được insight/nhu cầu thật của khách trước khi kết thúc cuộc gọi vẫn được tính là hoàn thành mục tiêu.', 'combo', true)
insert into public.levels
  (id, chapter_number, persona_id, product_id, star_rating, opening_line, sample_flow, objection_bank, win_criteria, is_final_boss)
values
('1.1', 1, 'noi-tro-tiet-kiem', 'tiet-kiem-online', 1, 'Cô vẫn quen ra quầy gửi tiết kiệm cho chắc, gửi online cô sợ mất tiền lắm, lỡ bị hack tài khoản thì sao?', '["Nhân viên trấn an: so sánh gửi online với gửi tại quầy — tiền vẫn nằm trong hệ thống ngân hàng, có mã OTP xác nhận riêng từng giao dịch.","Đưa ví dụ cụ thể: \"Cô chỉ cần 3 bước trên app, giống như cô nhắn tin Zalo cho con vậy đó.\"","Nhấn mạnh lợi ích thực tế: không phải đi lại, không phải xếp hàng, lãi suất online thường nhỉnh hơn tại quầy.","Đề xuất: làm mẫu ngay tại chỗ một lần để khách yên tâm."]'::jsonb, '[{"trigger":"Lỡ thao tác sai bấm nhầm mất tiền?","guidance":"Giải thích có bước xác nhận lại trước khi hoàn tất, không mất tiền do bấm nhầm."},{"trigger":"Con cô ở xa, ai giúp cô khi cần?","guidance":"Nhân viên hướng dẫn lưu số hotline hỗ trợ 24/7, có thể gọi bất cứ lúc nào."}]'::jsonb, 'Khách đồng ý thử mở tiết kiệm online, hoặc yêu cầu nhân viên hướng dẫn thao tác cụ thể trên app.', false),
('1.2', 1, 'noi-tro-tiet-kiem', 'the-tin-dung', 1, 'Thẻ tín dụng là vay nợ đúng không? Cô sợ xài quá tay rồi nợ nần, thấy trên báo đài nói nhiều người vỡ nợ vì thẻ.', '["Định vị lại: thẻ tín dụng là công cụ quản lý chi tiêu có hạn mức kiểm soát, không phải khoản vay tự động.","Ví dụ gần gũi: giống như một \"cuốn sổ ghi nợ chợ\" nhưng có hạn mức cứng và sao kê rõ ràng hàng tháng.","Nhấn điểm khách kiểm soát được: khách tự đặt hạn mức thấp ban đầu, có thể khoá thẻ tạm thời qua app bất cứ lúc nào.","Gợi ý lợi ích gia đình: dùng thẻ thanh toán siêu thị/điện nước, có ưu đãi hoàn tiền, dễ theo dõi hơn tiền mặt."]'::jsonb, '[{"trigger":"Lỡ con cái xài thẻ của cô thì sao?","guidance":"Có thể đặt thông báo biến động số dư ngay lập tức, khoá thẻ tức thì nếu nghi ngờ."},{"trigger":"Phí thường niên có mắc không?","guidance":"Trả lời trung thực, so sánh với lợi ích hoàn tiền/ưu đãi nếu dùng đều."}]'::jsonb, 'Khách hết lo về "vay nợ", đồng ý tìm hiểu thêm hạn mức phù hợp hoặc đăng ký mở thẻ.', false),
('1.3', 1, 'noi-tro-tiet-kiem', 'vay-tieu-dung', 1, 'Nhà cô đang cần sửa lại mái nhà, nhưng vay ngân hàng nghe thủ tục rắc rối lắm, hay là vay nóng ngoài cho lẹ?', '["Khai thác nhu cầu cụ thể: hỏi rõ số tiền cần, mục đích (sửa nhà/mua sắm), thời gian cần gấp hay không.","So sánh trực diện với \"vay nóng\": lãi suất minh bạch cố định, không lãi chồng lãi, không bị đe doạ đòi nợ.","Trấn an thủ tục: liệt kê ngắn gọn giấy tờ cần, thời gian giải ngân dự kiến, không cần thế chấp nếu khoản vay nhỏ.","Đưa ví dụ trả góp hàng tháng cụ thể để khách hình dung được khả năng chi trả."]'::jsonb, '[{"trigger":"Thủ tục có lâu không, sợ chờ lâu quá?","guidance":"Nêu rõ thời gian xử lý dự kiến, so sánh nhanh hơn nhiều lần so với chờ vay nóng \"gãy gánh\"."},{"trigger":"Lỡ trả trễ 1 tháng bị phạt nặng không?","guidance":"Giải thích rõ chính sách trễ hạn, không mập mờ."}]'::jsonb, 'Khách đồng ý cung cấp thông tin để tư vấn hạn mức vay cụ thể, không còn ý định tìm vay nóng.', false),
('1.4', 1, 'noi-tro-tiet-kiem', 'bao-hiem-lien-ket', 1, 'Bảo hiểm nghe phức tạp lắm, đóng tiền vào rồi không biết có lấy lại được không, cô không hiểu mấy cái đầu tư gì đâu.', '["Đơn giản hoá tối đa: chỉ nói về mục đích bảo vệ tài chính gia đình khi có rủi ro (ốm đau, tai nạn), không nhắc đến thuật ngữ đầu tư.","Dùng câu hỏi mở nhẹ nhàng: \"Nếu chẳng may cô hay chú ốm nặng, ai là người lo viện phí và chi tiêu gia đình?\"","Nêu ví dụ cụ thể, số tiền nhỏ dễ hình dung: \"Mỗi tháng để dành một khoản bằng tiền chợ vài ngày, đổi lại cả nhà được bảo vệ.\"","Tuyệt đối tránh liệt kê điều khoản phức tạp ngay từ đầu — chỉ giới thiệu khi khách đã quan tâm."]'::jsonb, '[{"trigger":"Đóng bao lâu, có rút ra giữa chừng được không?","guidance":"Trả lời thẳng, rõ ràng về thời hạn và điều kiện rút, không né tránh."},{"trigger":"Nghe hàng xóm nói đóng bảo hiểm bị mất tiền?","guidance":"Ghi nhận lo ngại, giải thích khác biệt giữa sản phẩm này và trường hợp họ nghe kể."}]'::jsonb, 'Khách hiểu đúng mục đích bảo vệ (không nhầm là đầu tư), đồng ý nghe thêm về mức phí phù hợp.', false),
('1.5', 1, 'noi-tro-tiet-kiem', 'combo', 1.5, 'Cô chỉ cần gửi tiết kiệm thôi, mấy cái khác cô không cần đâu, đừng giới thiệu thêm cho rối.', '["Tôn trọng yêu cầu ban đầu, không ép — bắt đầu đúng với tiết kiệm online như khách muốn.","Trong lúc tư vấn, đặt câu hỏi khai thác nhẹ nhàng: \"Cô có hay dùng thẻ ATM rút tiền không, có bao giờ cần một khoản vay gấp không?\"","Khi phát hiện nhu cầu ẩn (VD: khách nhắc tới việc sắp sửa nhà), mới giới thiệu thêm 1 sản phẩm liên quan — không giới thiệu tất cả cùng lúc.","Đề xuất combo như một \"giải pháp tiết kiệm hơn\" chứ không phải bán thêm: \"Nếu cô mở tiết kiệm và làm thêm thẻ ghi nợ liên kết, cô không mất phí quản lý tài khoản riêng.\""]'::jsonb, '[{"trigger":"Cô đã nói không cần rồi mà?","guidance":"Xin lỗi nhẹ nhàng, xác nhận lại đúng nhu cầu ban đầu, chỉ đề cập 1 lần duy nhất rồi dừng nếu khách từ chối."}]'::jsonb, 'Khai thác được ít nhất 1 nhu cầu ẩn và đề xuất đúng 1 sản phẩm bổ sung phù hợp, không làm khách khó chịu vì bị chào mời dồn dập.', false),
('2.1', 2, 'nv-van-phong-tre', 'tiet-kiem-online', 2, 'Lương về là mình tiêu gần hết, cuối tháng chẳng còn dư mà gửi tiết kiệm.', '["Đề xuất giải pháp \"tiết kiệm tự động\" ngay khi lương về, thay vì chờ cuối tháng mới gửi.","Đưa con số cụ thể nhỏ, dễ chấp nhận: \"Chỉ cần trích 10% lương ngay khi nhận, sau 1 năm sẽ có một khoản kha khá mà không cảm thấy thiếu.\"","Nhấn mạnh thao tác 100% qua app, thiết lập 1 lần là tự động, không cần nhớ để làm thủ công mỗi tháng."]'::jsonb, '[{"trigger":"Lỡ tháng nào cần tiền gấp thì sao?","guidance":"Giải thích có thể tất toán/rút linh hoạt trên app, không mất nhiều thời gian."}]'::jsonb, 'Khách đồng ý thiết lập trích tiết kiệm tự động hàng tháng.', false),
('2.2', 2, 'nv-van-phong-tre', 'the-tin-dung', 2, 'Mình hay mua hàng online, order đồ ăn, xem có thẻ nào hoàn tiền tốt không?', '["Khai thác nhanh thói quen chi tiêu: mua sắm online, ăn uống, đi lại — để chọn đúng dòng thẻ có ưu đãi phù hợp.","Đưa số liệu cụ thể: mức hoàn tiền %/danh mục, ưu đãi đối tác đang có.","Chốt nhanh, đúng phong cách khách: không lan man, đi thẳng vào lợi ích + bước đăng ký."]'::jsonb, '[{"trigger":"Phí thường niên có đáng không?","guidance":"So sánh nhanh: hoàn tiền ước tính theo mức chi tiêu hiện tại > phí thường niên."}]'::jsonb, 'Khách chốt mở thẻ ngay trong buổi tư vấn.', false),
('2.3', 2, 'nv-van-phong-tre', 'vay-tieu-dung', 2, 'Mình chưa cần vay gì cả, lương đủ sống mà.', '["Định vị sản phẩm là \"hạn mức dự phòng\", không phải khoản vay phải dùng ngay: mở sẵn để chủ động khi có nhu cầu bất ngờ (du lịch, mua sắm gấp, sự kiện phát sinh).","Giữ ngắn gọn, không ép: chỉ nêu lợi ích chính rồi để khách tự quyết.","Nhấn điểm không phát sinh phí nếu không sử dụng đến hạn mức."]'::jsonb, '[{"trigger":"Mở sẵn có ảnh hưởng gì đến điểm tín dụng không?","guidance":"Trả lời trung thực, ngắn gọn, đúng trọng tâm."}]'::jsonb, 'Khách đồng ý mở hạn mức dự phòng dù hiện tại chưa dùng đến.', false),
('2.4', 2, 'nv-van-phong-tre', 'bao-hiem-lien-ket', 2.5, 'Mình còn trẻ, khoẻ mạnh, bảo hiểm để sau đi, giờ ưu tiên hưởng thụ cuộc sống đã.', '["Không phản bác trực tiếp — đặt câu hỏi gợi mở: \"Bạn có biết phí bảo hiểm ở tuổi này thấp hơn rất nhiều so với 10 năm sau không?\"","Đưa góc nhìn tài chính: mua sớm = khoá được mức phí thấp dài hạn, không phải mua vì \"sợ bệnh\".","Gắn với mục tiêu cá nhân của khách (VD: mua nhà, kết hôn) — bảo hiểm như một phần kế hoạch tài chính dài hạn, không phải chi phí phát sinh."]'::jsonb, '[{"trigger":"Để dành tiền đó đi du lịch còn hơn?","guidance":"Không phủ nhận nhu cầu hưởng thụ, đề xuất mức phí rất nhỏ không ảnh hưởng ngân sách du lịch."}]'::jsonb, 'Khách đồng ý cân nhắc, không còn gạt phắt là "chưa cần".', false),
('2.5', 2, 'nv-van-phong-tre', 'combo', 2, 'Có gói nào gộp lại rẻ hơn không, mình không muốn đăng ký lắt nhắt từng cái mất thời gian?', '["Đề xuất combo thẳng: tiết kiệm tự động + thẻ tín dụng hoàn tiền, tính luôn phần tiết kiệm phí nếu đăng ký chung.","Chốt nhanh bằng một bảng so sánh ngắn: \"mua lẻ tốn X, mua combo tốn Y → tiết kiệm Z\".","Xác nhận đăng ký ngay trong buổi nói chuyện, đúng phong cách quyết nhanh của khách."]'::jsonb, '[{"trigger":"Combo có ràng buộc gì không, huỷ giữa chừng được không?","guidance":"Trả lời rõ ràng, không giấu điều khoản."}]'::jsonb, 'Khách chốt combo ngay, không cần suy nghĩ thêm nhiều ngày.', false),
('3.1', 3, 'chu-ho-kinh-doanh', 'tiet-kiem-online', 3, 'Anh có ít vốn nhàn rỗi tạm thời, gửi tiết kiệm ở đây lãi suất bao nhiêu, có hơn ngân hàng khác không?', '["Đưa ngay lãi suất cụ thể theo kỳ hạn, không vòng vo.","So sánh trực diện với mặt bằng thị trường nếu khách hỏi, trung thực nếu không nhỉnh hơn — bù lại bằng tính linh hoạt kỳ hạn/rút gốc linh hoạt.","Đề xuất kỳ hạn ngắn phù hợp với \"vốn nhàn rỗi tạm thời\" thay vì ép kỳ hạn dài."]'::jsonb, '[{"trigger":"Ngân hàng X trả lãi cao hơn 0.3%?","guidance":"Thừa nhận nếu đúng, đưa điểm bù lại (linh hoạt, dịch vụ, tốc độ xử lý)."}]'::jsonb, 'Khách đồng ý gửi tối thiểu 1 kỳ hạn thử nghiệm.', false),
('3.2', 3, 'chu-ho-kinh-doanh', 'the-tin-dung', 3, 'Anh có sẵn thẻ ghi nợ để chi tiêu cửa hàng rồi, cần gì thêm thẻ tín dụng nữa?', '["Phân biệt rõ mục đích: thẻ tín dụng dùng cho chi tiêu vận hành nhỏ lẻ (mua vật tư, thanh toán nhà cung cấp gấp), tách bạch khỏi vốn kinh doanh chính trong tài khoản ghi nợ.","Nhấn điểm dòng tiền: dùng thẻ tín dụng giúp giữ vốn lưu động lâu hơn (trả sau 45 ngày miễn lãi) thay vì rút tiền mặt ngay.","Đưa ví dụ tình huống cụ thể liên quan ngành hàng của khách."]'::jsonb, '[{"trigger":"Lỡ dùng quá tay ảnh hưởng dòng tiền kinh doanh?","guidance":"Đề xuất hạn mức phù hợp quy mô kinh doanh, không đề xuất hạn mức quá cao."}]'::jsonb, 'Khách hiểu rõ lợi ích tách bạch dòng tiền, đồng ý mở thẻ với hạn mức phù hợp.', false),
('3.3', 3, 'chu-ho-kinh-doanh', 'vay-tieu-dung', 3, 'Anh cần vốn xoay vòng nhập hàng đợt tới, lãi suất bên này sao, giải ngân nhanh không?', '["Trả lời thẳng bằng số liệu: lãi suất theo kỳ hạn, thời gian giải ngân dự kiến cụ thể (VD: 3–5 ngày làm việc).","Xử lý câu hỏi khó về lãi suất bằng cách giải thích cách tính (cố định hay giảm dần), không né tránh.","Đề xuất kỳ hạn vay khớp với chu kỳ xoay vòng vốn của khách (theo mùa vụ nhập hàng)."]'::jsonb, '[{"trigger":"Sao lãi suất bên này cao hơn tôi tính?","guidance":"Giải thích rõ cách tính lãi (dư nợ giảm dần vs cố định), đối chiếu số liệu cụ thể để khách so sánh đúng bản chất."},{"trigger":"Giải ngân có đúng hẹn không, trễ ảnh hưởng lịch nhập hàng?","guidance":"Cam kết mốc thời gian cụ thể, nêu rõ điều kiện để đảm bảo đúng tiến độ."}]'::jsonb, 'Khách đồng ý nộp hồ sơ vay với hạn mức và kỳ hạn cụ thể đã thống nhất.', false),
('3.4', 3, 'chu-ho-kinh-doanh', 'bao-hiem-lien-ket', 3.5, 'Anh còn đang bận xoay vốn kinh doanh, bảo hiểm để tính sau, giờ ưu tiên dòng tiền hơn.', '["Không tranh luận trực tiếp về ưu tiên — đặt câu hỏi liên hệ tới rủi ro kinh doanh: \"Nếu anh phải nằm viện 1–2 tháng, ai vận hành cửa hàng, dòng tiền có bị gián đoạn không?\"","Định vị bảo hiểm như một \"quỹ dự phòng rủi ro cho chính người trụ cột\", không cạnh tranh với vốn kinh doanh.","Đề xuất mức phí nhỏ, không ảnh hưởng đáng kể dòng tiền hiện tại."]'::jsonb, '[{"trigger":"Tiền đó để đầu tư thêm vào cửa hàng còn lời hơn?","guidance":"Ghi nhận logic đầu tư, nhưng nhấn mạnh đây là quỹ dự phòng rủi ro, khác bản chất với vốn đầu tư sinh lời."}]'::jsonb, 'Khách đồng ý dành một khoản nhỏ, tách biệt khỏi vốn kinh doanh, cho mục đích bảo vệ tài chính cá nhân.', false),
('3.5', 3, 'chu-ho-kinh-doanh', 'combo', 3.5, 'Anh có ít tài sản tích luỹ rồi, muốn nghe giải pháp tổng thể luôn, đừng giới thiệu từng cái lẻ tẻ mất thời gian.', '["Khai thác nhanh bức tranh tài chính tổng thể: tài sản hiện có, dòng tiền kinh doanh, mục tiêu dài hạn (mở rộng/để lại cho con cái...).","Đề xuất giải pháp toàn diện có số liệu đi kèm: kỳ hạn tiết kiệm nào, hạn mức thẻ/vay nào, mức phí bảo hiểm nào — trình bày như một bảng tổng hợp ngắn gọn.","Chuẩn bị sẵn số liệu so sánh vì khách hay đối chiếu với ngân hàng khác."]'::jsonb, '[{"trigger":"Sao không thấy rẻ hơn tự mua lẻ từng sản phẩm?","guidance":"Đưa bảng số liệu cụ thể chứng minh phần tiết kiệm/ưu đãi khi mua combo."}]'::jsonb, 'Khách đồng ý với ít nhất 2/4 sản phẩm trong đề xuất combo, dựa trên số liệu đã thuyết phục được.', false),
('4.1', 4, 'nguoi-da-nghi', 'tiet-kiem-online', 4, 'Trước tôi từng bị lừa mất tiền qua app rồi, giờ nghe "online" là tôi ngại lắm.', '["Không vội bán hàng — dành thời gian lắng nghe khách kể lại chuyện cũ, thể hiện sự thấu hiểu thật sự.","Giải thích khác biệt cụ thể giữa ứng dụng ngân hàng chính thức và các app/link lừa đảo (dấu hiệu nhận biết, cơ chế bảo mật OTP/sinh trắc học).","Đề xuất bắt đầu với số tiền rất nhỏ để khách tự trải nghiệm an toàn trước khi tin tưởng gửi khoản lớn hơn."]'::jsonb, '[{"trigger":"Sao tôi biết đây không phải chiêu trò mới?","guidance":"Không tranh cãi, mời khách tự kiểm tra qua tổng đài chính thức/website ngân hàng để xác minh độc lập."}]'::jsonb, 'Khách đồng ý thử gửi một khoản nhỏ để tự kiểm chứng, không cần chốt khoản lớn ngay.', false),
('4.2', 4, 'nguoi-da-nghi', 'the-tin-dung', 4, 'Thẻ tín dụng toàn bẫy nợ, phí ẩn đủ kiểu, tôi không tin đâu.', '["Minh bạch hoàn toàn ngay từ đầu: liệt kê rõ tất cả các loại phí có thể phát sinh (thường niên, phí trễ hạn, lãi suất nếu không trả đủ), kể cả phần bất lợi.","Không né tránh câu hỏi khó, chủ động nêu trước cả những nhược điểm.","Đề xuất hạn mức thấp và các công cụ kiểm soát (thông báo biến động, khoá thẻ tức thời) để khách cảm thấy nắm quyền kiểm soát."]'::jsonb, '[{"trigger":"Vậy sao ngân hàng không nói rõ từ đầu với người khác?","guidance":"Không biện minh cho ai khác, chỉ cam kết phần tư vấn của mình minh bạch."}]'::jsonb, 'Khách xác nhận đã hiểu rõ và không còn cảm giác bị giấu diếm thông tin, dù chưa chắc đăng ký ngay.', false),
('4.3', 4, 'nguoi-da-nghi', 'vay-tieu-dung', 4, 'Vay ngân hàng là dính vào nợ nần, tôi từng thấy người quen vay xong lãi mẹ đẻ lãi con.', '["Xác nhận cảm xúc của khách trước, không phản bác ngay.","Giải thích minh bạch cách tính lãi, không có khái niệm \"lãi chồng lãi\" như vay tín dụng đen, đưa ví dụ số cụ thể từng tháng.","Tuyệt đối không hối thúc — chủ động nói khách có thể về suy nghĩ thêm, không cần quyết định ngay hôm nay."]'::jsonb, '[{"trigger":"Tôi cần nghĩ thêm, chưa quyết ngay được.","guidance":"Tôn trọng, không tạo áp lực, để lại thông tin liên hệ và mời khách quay lại khi sẵn sàng."}]'::jsonb, 'Khách không còn phòng thủ gay gắt, dù có thể chưa chốt vay ngay trong buổi này — mục tiêu là giữ được niềm tin.', false),
('4.4', 4, 'nguoi-da-nghi', 'bao-hiem-lien-ket', 5, 'Tôi từng mua bảo hiểm, tư vấn viên hứa đủ thứ, sau này đọc hợp đồng mới biết không như lời nói. Từ đó tôi cạch bảo hiểm luôn.', '["Xin lỗi thay cho trải nghiệm xấu khách từng gặp (dù không phải lỗi của mình), thể hiện sự đồng cảm chân thành.","Tuân thủ disclosure tuyệt đối: đọc/chỉ rõ từng điều khoản quan trọng cùng khách, đặc biệt các điểm dễ gây hiểu lầm trước đây (quyền lợi, loại trừ, phí duy trì hợp đồng).","Không dùng bất kỳ lời \"hứa\" nào ngoài văn bản hợp đồng — mọi cam kết đều trỏ lại điều khoản cụ thể.","Đề xuất khách mang hợp đồng cũ ra để đối chiếu minh bạch nếu có thể."]'::jsonb, '[{"trigger":"Sao tôi tin lần này khác lần trước?","guidance":"Không cần khách tin ngay, mời khách tự đọc kỹ hợp đồng, tự do hỏi bất kỳ điều khoản nào trước khi quyết định."}]'::jsonb, 'Khách đồng ý đọc thử hợp đồng mẫu hoặc đặt câu hỏi cụ thể — không rời đi trong tức giận. Chốt được hợp đồng là thành công lớn nhưng không phải mục tiêu bắt buộc của level.', false),
('4.5', 4, 'nguoi-da-nghi', 'combo', 4.5, 'Tôi mới bắt đầu tin lại một chút sau mấy lần nói chuyện trước, nhưng đừng có chào mời dồn dập nha.', '["Ghi nhận rõ tiến trình xây dựng niềm tin từ các level trước, cảm ơn khách đã cho cơ hội.","Đề xuất combo rất nhẹ nhàng, đóng khung là \"gợi ý tham khảo\" chứ không phải chào mời ép buộc.","Ưu tiên tuyệt đối: nếu khách có dấu hiệu do dự, chủ động lùi lại thay vì cố chốt bằng mọi giá."]'::jsonb, '[{"trigger":"Nãy giờ tin rồi giờ lại đề xuất thêm nữa à?","guidance":"Xin lỗi nếu khách cảm thấy vậy, khẳng định lại đây chỉ là gợi ý, khách toàn quyền từ chối."}]'::jsonb, 'Giữ được niềm tin đến cuối buổi là ưu tiên số 1; nếu khách đồng ý thêm 1 sản phẩm nữa thì là điểm cộng, không bắt buộc.', false),
('5.1', 5, 'khach-vip', 'tiet-kiem-online', 4, 'Gửi tiết kiệm vài chục tỷ mà lãi suất niêm yết công khai như người thường thì tôi gửi ở đâu chẳng được.', '["Không dùng bảng lãi suất đại trà — đề xuất ngay cơ chế lãi suất thoả thuận riêng theo số dư và kỳ hạn.","Giới thiệu dịch vụ cá nhân hoá đi kèm: chuyên viên quan hệ khách hàng riêng, ưu tiên xử lý giao dịch không cần xếp hàng.","Giữ phong thái tự tin, đúng tầm — không giải thích dài dòng những gì khách đã biết."]'::jsonb, '[{"trigger":"Ngân hàng khác cũng đề nghị mức tương tự.","guidance":"Đưa thêm giá trị đi kèm ngoài lãi suất (dịch vụ, tốc độ, đặc quyền) để tạo khác biệt."}]'::jsonb, 'Khách đồng ý gửi ít nhất một phần tài sản với mức lãi suất/dịch vụ đã thoả thuận riêng.', false),
('5.2', 5, 'khach-vip', 'the-tin-dung', 4.5, 'Thẻ vàng thẻ bạc gì tôi có đủ hết rồi, cho tôi xem cái gì đặc biệt hơn.', '["Giới thiệu thẳng dòng thẻ cao cấp nhất, nhấn vào đặc quyền độc quyền (phòng chờ sân bay riêng, trợ lý cá nhân, hạn mức không giới hạn theo nhu cầu thực tế) thay vì ưu đãi hoàn tiền đại trà.","Cá nhân hoá theo lối sống khách (du lịch nhiều, chi tiêu cao cấp) nếu có thông tin gợi mở."]'::jsonb, '[{"trigger":"Đặc quyền này ngân hàng nào chẳng có?","guidance":"Nêu điểm khác biệt cụ thể, thật sự riêng biệt (không nói chung chung)."}]'::jsonb, 'Khách công nhận điểm khác biệt thực sự và đồng ý mở thẻ cao cấp.', false),
('5.3', 5, 'khach-vip', 'vay-tieu-dung', 4.5, 'Tôi cần hạn mức lớn, lãi suất phải tốt hơn mặt bằng, không thì tôi qua bên khác.', '["Không hoảng, giữ thế đàm phán bình đẳng: xác nhận nhu cầu cụ thể rồi đề xuất mức lãi suất ưu tiên có cơ sở (dựa trên tài sản đảm bảo/quan hệ khách hàng lâu năm).","Đàm phán có giới hạn rõ ràng trong thẩm quyền, không hứa hẹn quá mức để rồi thất hứa."]'::jsonb, '[{"trigger":"Mức đó vẫn chưa đủ tốt.","guidance":"Đề xuất điều kiện đổi lại (VD: cam kết giao dịch dài hạn) để có thêm dư địa đàm phán, không hạ giá vô điều kiện."}]'::jsonb, 'Đạt được thoả thuận về hạn mức/lãi suất mà cả hai bên chấp nhận được, không nhượng bộ quá thẩm quyền.', false),
('5.4', 5, 'khach-vip', 'bao-hiem-lien-ket', 5, 'Mức phí này so với quyền lợi tôi thấy chưa tương xứng, tư vấn viên trước không trả lời được câu hỏi của tôi.', '["Thể hiện kiến thức sản phẩm vững: trả lời chính xác, có căn cứ mọi câu hỏi kỹ thuật về quyền lợi/loại trừ/cách tính phí.","Đàm phán kỹ về mức phí và quyền lợi trong phạm vi được phép, đưa ra phương án tuỳ chỉnh gói bảo hiểm phù hợp tài sản/nhu cầu khách.","Không né tránh câu hỏi khó — nếu chưa chắc, cam kết xác nhận lại chính xác thay vì trả lời qua loa."]'::jsonb, '[{"trigger":"Sao mức phí VIP không thấp hơn tương xứng?","guidance":"Giải thích cơ cấu phí dựa trên quyền lợi mở rộng, không giảm phí tuỳ tiện thiếu căn cứ."}]'::jsonb, 'Khách công nhận nhân viên nắm vững sản phẩm, đồng ý với gói quyền lợi đã tuỳ chỉnh.', false),
('5.5', 5, 'khach-vip', 'combo', 5, 'Tôi có tài sản ở nhiều nơi, mục tiêu tài chính dài hạn khá phức tạp, anh/chị đề xuất được gì cho tôi thì nói, không thì đừng mất thời gian của cả hai.', '["Khai thác insight tổng thể trước khi đề xuất bất cứ điều gì: tài sản hiện có, mục tiêu dài hạn (kế thừa, mở rộng kinh doanh, nghỉ hưu), khẩu vị rủi ro.","Xây dựng đề xuất combo cá nhân hoá hoàn toàn dựa trên insight vừa khai thác — không dùng kịch bản combo có sẵn.","Trình bày tự tin, súc tích, đi thẳng vào giá trị riêng biệt dành cho khách, chuẩn bị tinh thần bị \"dập máy\" bất cứ lúc nào nếu không đủ thuyết phục ngay từ đầu.","Đây là level thể hiện rõ nhất tinh thần: khai thác insight đủ sâu + đề xuất combo thuyết phục trước khi khách mất kiên nhẫn."]'::jsonb, '[{"trigger":"Nghe vẫn giống công thức chung chung.","guidance":"Quay lại đào sâu thêm 1 insight cụ thể, điều chỉnh đề xuất ngay tại chỗ."},{"trigger":"Tôi cần thời gian suy nghĩ.","guidance":"Chấp nhận nhưng chốt được bước tiếp theo rõ ràng (hẹn buổi tiếp theo, gửi đề xuất bằng văn bản)."}]'::jsonb, 'Đề xuất được combo cá nhân hoá dựa trên ít nhất 2–3 insight khai thác được, khách đồng ý bước tiếp theo cụ thể (không nhất thiết phải chốt hợp đồng ngay).', true)
insert into public.quiz_questions
  (level_id, question_order, question, options, correct_option_id, explanation)
values
('1.1', 1, 'Để mở sổ tiết kiệm online tại MSB, khách hàng cần đáp ứng điều kiện cơ bản nào?', '[{"id":"A","text":"Có tài khoản thanh toán MSB và số tiền gửi tối thiểu 5.000.000đ"},{"id":"B","text":"Ra trực tiếp chi nhánh để ký hợp đồng và nộp tiền mặt"},{"id":"C","text":"Có tài khoản thanh toán MSB và số tiền gửi tối thiểu 1.000.000đ"},{"id":"D","text":"Chỉ dành cho khách hàng doanh nghiệp với số dư trung bình cao"}]'::jsonb, 'C', 'Điều kiện cơ bản là có tài khoản thanh toán MSB và số tiền gửi tối thiểu từ 1.000.000đ.'),
('1.1', 2, 'Khi khách hàng lo lắng về việc ''gửi online có an toàn không, lỡ mất tiền thì sao'', nhân viên nên trả lời chuẩn như thế nào?', '[{"id":"A","text":"Gửi online chỉ an toàn nếu khách hàng tự bảo mật mật khẩu, ngân hàng không chịu trách nhiệm"},{"id":"B","text":"Tiền gửi được bảo hiểm theo quy định của Nhà nước, sổ điện tử có giá trị pháp lý tương đương sổ giấy"},{"id":"C","text":"Ngân hàng sẽ hoàn trả 100% giá trị nếu có sự cố kỹ thuật từ phía đối tác công nghệ"},{"id":"D","text":"Khách hàng nên gửi tại quầy để đảm bảo an toàn tuyệt đối nhất có thể"}]'::jsonb, 'B', 'Trả lời chuẩn nhấn mạnh tính an toàn tương đương tại quầy, được bảo hiểm tiền gửi theo quy định NHNN và giá trị pháp lý của sổ điện tử.'),
('1.1', 3, 'Khách hàng nghi ngờ ''lãi suất online cao hơn tại quầy thật không hay chỉ là quảng cáo''. Câu trả lời nào sau đây là chính xác?', '[{"id":"A","text":"Đây là chính sách chính thức của ngân hàng, khách hàng có thể xem bảng lãi suất minh bạch trong app theo thời gian thực"},{"id":"B","text":"Lãi suất cao hơn là do ưu đãi đặc biệt chỉ áp dụng cho một nhóm khách hàng thân thiết"},{"id":"C","text":"Nhân viên sẽ gửi tin nhắn xác nhận lãi suất cụ thể qua Zalo sau khi đăng ký thành công"},{"id":"D","text":"Lãi suất online thay đổi liên tục nên khó dự đoán, tốt nhất nên hỏi nhân viên trực tiếp"}]'::jsonb, 'A', 'Lãi suất online cao hơn là chính sách chính thức, minh bạch và có thể kiểm chứng trực tiếp trên app.'),
('1.1', 4, 'Nếu khách hàng rút tiền trước hạn (gấp), nhân viên giải thích về lãi suất như thế nào?', '[{"id":"A","text":"Toàn bộ số tiền sẽ bị tính lãi suất 0%/năm do vi phạm kỳ hạn cam kết"},{"id":"B","text":"Phần tiền gửi đủ kỳ hạn tối thiểu vẫn được tính lãi không kỳ hạn, không bị mất trắng như trước đây"},{"id":"C","text":"Khách hàng sẽ bị phạt phí quản lý 1% tổng giá trị tài khoản rút trước hạn"},{"id":"D","text":"Lãi suất sẽ được giữ nguyên như khi gửi nhưng phải chờ đến cuối kỳ hạn mới được rút"}]'::jsonb, 'B', 'Chính sách linh hoạt cho phép rút trước hạn mà phần tiền gửi đủ kỳ hạn tối thiểu vẫn được tính lãi không kỳ hạn.'),
('1.1', 5, 'Đối với khách hàng lớn tuổi (38-55 tuổi) ngại công nghệ, lo sợ ''bấm nhầm mất tiền'' hoặc ''không biết thao tác'', nhân viên xử lý ra sao?', '[{"id":"A","text":"Khuyên khách hàng nhờ con cháu thực hiện giúp vì họ rành công nghệ hơn"},{"id":"B","text":"Giải thích thao tác chỉ 3 bước đơn giản, có hướng dẫn trong app, có xác nhận lại trước khi hoàn tất và hỗ trợ hotline 24/7"},{"id":"C","text":"Yêu cầu khách hàng ra quầy để nhân viên trực tiếp thực hiện lệnh chuyển tiền giúp"},{"id":"D","text":"Hướng dẫn khách hàng sử dụng thẻ ATM tự động thay vì dùng app mobile banking"}]'::jsonb, 'B', 'Nhấn mạnh sự đơn giản (3 bước), cơ chế xác nhận chống bấm nhầm, cùng với hỗ trợ hướng dẫn và hotline 24/7 để giảm bớt lo ngại.'),
('1.2', 1, 'Khi tư vấn cho khách hàng là nội trợ quan tâm đến việc quản lý chi tiêu gia đình, nhân viên cần nhấn mạnh điểm nào sau đây để giải quyết nỗi sợ ''dễ nợ nần, khó kiểm soát''? (Dựa trên Objection bank chung)', '[{"id":"A","text":"Khuyến khích khách hàng sử dụng thẻ tối đa trong ngày đầu để hưởng ưu đãi lớn."},{"id":"B","text":"Nhấn mạnh rằng App có công cụ theo dõi chi tiêu thời gian thực, đặt được hạn mức cảnh báo và hạn mức cấp phát dựa trên thu nhập thực tế nên không vượt khả năng chi trả."},{"id":"C","text":"Cam kết miễn lãi vĩnh viễn 100% nếu khách hàng không bao giờ thanh toán chậm dù chỉ một ngày."},{"id":"D","text":"Khuyên khách hàng không cần theo dõi sao kê vì phí thường niên đã được miễn hoàn toàn."}]'::jsonb, 'B', 'Câu trả lời đúng phản ánh chính xác giải pháp kỹ số (App) và nguyên tắc cấp hạn mức dựa trên thu nhập để giảm thiểu rủi ro nợ nần, giúp khách hàng yên tâm kiểm soát tài chính.'),
('1.2', 2, 'Trong tình huống khách hàng là người quản lý chi tiêu gia đình lo lắng về việc con cái sử dụng thẻ trái phép, nhân viên nên đề xuất tính năng nào? (Dựa trên Objection bank riêng của tình huống)', '[{"id":"A","text":"Yêu cầu khách hàng giữ thẻ vật lý ở nhà ngân hàng để tránh bị lấy cắp."},{"id":"B","text":"Hạn chế số lượng giao dịch con cái được phép thực hiện mỗi tháng."},{"id":"C","text":"Thiết lập thông báo biến động số dư ngay lập tức và khả năng khoá thẻ tức thì nếu nghi ngờ có bất thường."},{"id":"D","text":"Từ chối mở thẻ cho đối tượng này vì rủi ro an ninh quá cao."}]'::jsonb, 'C', 'Tính năng thông báo real-time và khoá thẻ tức thì là giải pháp trực tiếp nhất để quản lý rủi ro khi người khác (như con cái) sử dụng thẻ, đảm bảo an toàn tuyệt đối cho chủ thẻ.'),
('1.2', 3, 'Khi khách hàng hỏi: ''Phí thường niên có đắt không?'', nhân viên cần truyền tải thông tin gì đúng với chính sách sản phẩm? (Dựa trên Objection bank chung)', '[{"id":"A","text":"Miễn phí hoàn toàn năm đầu; các năm sau có thể tiếp tục miễn nếu đạt doanh số chi tiêu tối thiểu theo chính sách."},{"id":"B","text":"Không có phí thường niên mãi mãi nhưng sẽ tăng lãi suất nếu không dùng thẻ."},{"id":"C","text":"Miễn phí năm đầu, nhưng từ năm thứ hai bắt buộc phải đóng phí cố định bất kể mức chi tiêu."},{"id":"D","text":"Phí thường niên rất rẻ, chỉ khoảng 50.000 VNĐ/năm và không yêu cầu điều kiện duy trì."}]'::jsonb, 'A', 'Thông tin này chính xác về cam kết miễn phí năm đầu và cơ chế miễn phí gia hạn dựa trên doanh số, giúp khách hàng thấy rõ lợi ích tài chính thực tế.'),
('1.2', 4, 'Khách hàng nói: ''Tôi đã có thẻ tín dụng của ngân hàng khác rồi''. Theo quy trình xử lý phản đối chuẩn, bước tiếp theo nhân viên nên làm gì? (Dựa trên Objection bank chung)', '[{"id":"A","text":"Lập tức so sánh lãi suất thấp hơn của ngân hàng mình mà không cần hỏi thêm."},{"id":"B","text":"Đưa ra brochure giới thiệu tất cả các loại thẻ đang có của ngân hàng."},{"id":"C","text":"Khai thác nhu cầu bằng cách hỏi xem thẻ hiện tại còn thiếu ưu đãi gì, sau đó so sánh điểm khác biệt về hoàn tiền/tích điểm."},{"id":"D","text":"Chấp nhận từ chối và chuyển sang tư vấn sản phẩm tiết kiệm thay thế."}]'::jsonb, 'C', 'Chiến lược đúng là khai thác lỗ hổng của sản phẩm đối thủ (thiếu ưu đãi) trước khi đưa ra sự so sánh trực tiếp, giúp tạo giá trị gia tăng thuyết phục hơn là chỉ liệt kê đặc điểm.'),
('1.2', 5, 'Để khuyến khích khách hàng mở thẻ nhanh chóng, nhân viên cần nhấn mạnh quy trình và điều kiện cơ bản nào? (Dựa trên Key selling points và Điều kiện cơ bản)', '[{"id":"A","text":"Khách hàng cần đến trực tiếp chi nhánh, mang theo sổ hộ khẩu và nộp hồ sơ giấy mất 3-5 ngày làm việc."},{"id":"B","text":"Mở thẻ hoàn toàn qua app, hồ sơ đơn giản, duyệt trong vài phút, yêu cầu đủ 18 tuổi và chứng minh thu nhập (lương chuyển khoản/hợp đồng)."},{"id":"C","text":"Chỉ dành cho người có thu nhập trên 50 triệu/tháng và phải ký hợp đồng vay vốn phức tạp."},{"id":"D","text":"Cần có người bảo lãnh là người thân và thời gian chờ duyệt trung bình 7 ngày."}]'::jsonb, 'B', 'Đây là sự kết hợp chính xác giữa Key Selling Point (mở thẻ nhanh qua app) và Điều kiện cơ bản (tuổi tác, chứng minh thu nhập), tạo sự thuận tiện và dễ hiểu cho khách hàng mục tiêu.'),
('1.3', 1, 'Khi khách hàng là nội trợ 38-55 tuổi lo ngại ''Lãi suất vay tiêu dùng thường cao lắm'', nhân viên nên trả lời chuẩn như thế nào?', '[{"id":"A","text":"Khẳng định lãi suất cố định thấp nhất thị trường cho mọi đối tượng"},{"id":"B","text":"Giải thích mức lãi phụ thuộc hồ sơ, vẫn thấp hơn vay nóng bên ngoài và minh bạch ngay từ đầu"},{"id":"C","text":"Khuyên khách hàng chỉ vay nếu có tài sản đảm bảo để giảm lãi suất"},{"id":"D","text":"Nói rằng lãi suất sẽ được thương lượng sau khi ký hợp đồng"}]'::jsonb, 'B', 'Câu trả lời đúng dựa trên objection bank chuẩn: nhấn mạnh sự linh động theo hồ sơ, so sánh có lợi với vay nóng và tính minh bạch.'),
('1.3', 2, 'Khách hàng trong tình huống này hỏi: ''Thủ tục vay có phức tạp, mất nhiều thời gian không?''. Phương án nào thể hiện đúng quy trình của sản phẩm?', '[{"id":"A","text":"Cần đến trực tiếp chi nhánh, cung cấp sổ đỏ và chờ xét duyệt 7 ngày làm việc"},{"id":"B","text":"Hồ sơ đơn giản, xét duyệt online, có thể giải ngân ngay trong ngày nếu hồ sơ đầy đủ"},{"id":"C","text":"Yêu cầu người thân đứng ra bảo lãnh và mất 3-5 ngày để phê duyệt"},{"id":"D","text":"Phải thực hiện qua ứng dụng nhưng chỉ giải ngân vào thứ 6 hàng tuần"}]'::jsonb, 'B', 'Key selling point nhấn mạnh thủ tục đơn giản, xét duyệt online và khả năng giải ngân nhanh (có thể cùng ngày).'),
('1.3', 3, 'Nếu khách hàng nói ''Tôi sợ không trả nợ đúng hạn'' do áp lực chi tiêu gia đình, hành động nào nhân viên nên đề xuất?', '[{"id":"A","text":"Đề nghị khách hàng vay số tiền tối đa để chủ động tài chính"},{"id":"B","text":"Gợi ý cùng tính toán số tiền góp phù hợp thu nhập và chọn kỳ hạn để khoản trả hàng tháng thoải mái nhất"},{"id":"C","text":"Khuyên khách hàng tự tìm nguồn vay nóng khác nếu không đủ khả năng chi trả"},{"id":"D","text":"Bỏ qua lo ngại này vì lãi suất đã thấp rồi"}]'::jsonb, 'B', 'Câu trả lời chuẩn giúp giảm bớt áp tâm lý bằng cách tư vấn tính toán khả năng chi trả thực tế và lựa chọn kỳ hạn phù hợp.'),
('1.3', 4, 'Trong tình huống riêng của nhóm khách hàng nội trợ, khi họ hỏi ''Lỡ trả trễ 1 tháng bị phạt nặng không?'', nhân viên cần xử lý ra sao?', '[{"id":"A","text":"Không nhắc đến hình phạt để tránh gây căng thẳng cho khách"},{"id":"B","text":"Giải thích rõ ràng chính sách phạt trễ hạn cụ thể, tránh mập mờ"},{"id":"C","text":"Khoe rằng ngân hàng miễn phí phạt hoàn toàn cho mọi trường hợp"},{"id":"D","text":"Bảo khách hàng đừng quan tâm vì lãi suất thấp thì không sao"}]'::jsonb, 'B', 'Kiến thức sản phẩm yêu cầu minh bạch về chính sách phạt để xây dựng niềm tin, không được mập mờ hoặc bỏ qua rủi ro tín dụng.'),
('1.3', 5, 'Khách hàng phản hồi ''Tôi chưa có nhu cầu vay ngay bây giờ''. Phản ứng nào phù hợp với kỹ thuật giữ liên hệ và giới hạn dự phòng?', '[{"id":"A","text":"Chào tạm biệt vì khách không quan tâm"},{"id":"B","text":"Thuyết phục khách vay ngay để tích điểm thành viên"},{"id":"C","text":"Không sao, gợi ý giữ liên hệ và giới thiệu hạn mức vay dự phòng sẵn có qua app để dùng khi cần"},{"id":"D","text":"Yêu cầu khách đăng ký vay thử nghiệm dù chưa cần tiền"}]'::jsonb, 'C', 'Đây là câu trả lời chuẩn trong objection bank: tôn trọng quyết định hiện tại nhưng tạo cơ hội sử dụng hạn mức dự phòng linh hoạt qua app khi có nhu cầu.'),
('1.4', 1, 'Khi khách hàng là nội trợ lo lắng về rủi ro mất tiền trong phần đầu tư của sản phẩm bảo hiểm liên kết, nhân viên nên trả lời chuẩn như thế nào?', '[{"id":"A","text":"Cam kết chắc chắn không bao giờ mất tiền vì đây là bảo hiểm nhân thọ."},{"id":"B","text":"Giải thích rằng sản phẩm gồm phần bảo vệ cố định và phần đầu tư có nhiều mức rủi ro để lựa chọn, mọi thông tin đều minh bạch trong hợp đồng."},{"id":"C","text":"Khuyến nghị khách hàng bỏ qua phần đầu tư và chỉ mua phần bảo vệ thuần túy."},{"id":"D","text":"Bảo đảm rằng lãi suất luôn cao hơn lạm phát nên không có nguy cơ thua lỗ."}]'::jsonb, 'B', 'Câu trả lời đúng nhấn mạnh cấu trúc 2 phần của sản phẩm và tính minh bạch, giúp khách hàng hiểu rõ cơ chế rủi ro thay vì cam kết sai lệch.'),
('1.4', 2, 'Nếu khách hàng nói ''Tôi còn trẻ, chưa cần bảo hiểm'', hãy chọn câu trả lời phù hợp nhất với key selling points.', '[{"id":"A","text":"Đúng vậy, ở độ tuổi này sức khỏe tốt nên không cần thiết phải chi thêm."},{"id":"B","text":"Tham gia càng sớm, mức phí càng thấp và thời gian tích lũy càng dài — đây chính là thời điểm tối ưu nhất để bắt đầu."},{"id":"C","text":"Nếu không mua ngay thì lần sau sẽ tăng phí gấp đôi nên anh/chị nên cân nhắc."},{"id":"D","text":"Bảo hiểm chỉ dành cho người lớn tuổi hoặc người có bệnh lý nền mới cần thiết."}]'::jsonb, 'B', 'Lợi thế cốt lõi khi tham gia sớm là phí thấp hơn và quỹ thời gian tích lũy dài hạn hơn, đây là lý do thuyết phục nhất cho đối tượng trẻ.'),
('1.4', 3, 'Đối với khách hàng phản đối ''Phí đóng hàng năm cao quá, tôi không đủ khả năng'', phương án xử lý nào là chính xác?', '[{"id":"A","text":"Khuyên khách hàng tìm nguồn vay vốn để đóng phí nhằm giữ hợp đồng hiệu lực."},{"id":"B","text":"Nhấn mạnh rằng nếu không đóng thì sẽ mất toàn bộ số tiền đã đóng trước đó."},{"id":"C","text":"Thông báo rằng mức phí là cố định và không thể thay đổi theo từng giai đoạn."},{"id":"D","text":"Có thể điều chỉnh mức phí phù hợp với thu nhập hiện tại, không nhất thiết phải chọn gói cao nhất ngay từ đầu."}]'::jsonb, 'D', 'Tính linh hoạt trong việc điều chỉnh mức phí là điểm mạnh giúp giải quyết rào cản về ngân sách của khách hàng nội trợ.'),
('1.4', 4, 'Khi khách hàng hỏi về quyền lợi rút tiền giữa chừng hoặc hủy hợp đồng trong giai đoạn đầu, nhân viên cần truyền tải thông tin gì?', '[{"id":"A","text":"Không được rút tiền dưới bất kỳ hình thức nào cho đến khi hết hợp đồng 20 năm."},{"id":"B","text":"Có quyền cân nhắc/hủy trong 21 ngày đầu (thời gian cân nhắc) sau khi ký hợp đồng."},{"id":"C","text":"Chỉ được rút tiền một lần duy nhất sau 5 năm đóng phí."},{"id":"D","text":"Việc rút tiền bị trừ đi 50% giá trị hợp đồng nếu thực hiện trước năm thứ 3."}]'::jsonb, 'B', 'Quyền cân nhắc 21 ngày là yếu tố quan trọng tạo sự an tâm và chủ động cho khách hàng, đặc biệt với những người thận trọng.'),
('1.4', 5, 'Khách hàng chia sẻ ''Nghe hàng xóm nói đóng bảo hiểm bị mất tiền''. Hành động nào sau đây là phù hợp nhất với tình huống objection bank riêng này?', '[{"id":"A","text":"Chứng minh hàng xóm đó đã mua sai sản phẩm và khuyên khách hàng đừng nghe lời dị nghị."},{"id":"B","text":"Ghi nhận lo ngại, giải thích sự khác biệt giữa trường hợp họ nghe kể và cơ chế minh bạch của sản phẩm hiện tại."},{"id":"C","text":"Đồng ý rằng thị trường bảo hiểm hiện nay rủi ro rất cao và nên trì hoãn quyết định."},{"id":"D","text":"Tập trung vào việc giảm giá thành sản phẩm để cạnh tranh với trải nghiệm tiêu cực kia."}]'::jsonb, 'B', 'Cách tiếp cận empaty (ghi nhận lo ngại) và so sánh khách quan giúp xây dựng niềm tin mà không làm mất lòng khách hàng hay tấn công đối thủ.'),
('1.5', 1, 'Khi tư vấn Combo (Tài khoản số + Bảo hiểm + Đầu tư) cho khách hàng là nội trợ quản lý chi tiêu, điểm bán hàng chính nào sau đây là phù hợp nhất để thuyết phục họ về giá trị tổng thể?', '[{"id":"A","text":"Cam kết lợi nhuận đầu tư cao hơn thị trường mỗi tháng"},{"id":"B","text":"Giải pháp tài chính toàn diện, tiết kiệm chi phí tổng thể so với mua lẻ và không bị chắp vá từng phần"},{"id":"C","text":"Bắt buộc khách hàng phải mở tất cả các sản phẩm cùng lúc để nhận ưu đãi"},{"id":"D","text":"Miễn phí hoàn toàn dịch vụ chuyển tiền quốc tế không giới hạn"}]'::jsonb, 'B', 'Key selling point nhấn mạnh vào tính toàn diện, tiết kiệm chi phí khi kết hợp và sự linh hoạt, tránh cảm giác ép buộc hay cam kết lợi nhuận không thực tế.'),
('1.5', 2, 'Khách hàng phản đối: ''Nghe combo là thấy bị ép mua thêm cái không cần.'' Nhân viên nên trả lời chuẩn như thế nào?', '[{"id":"A","text":"Combo bắt buộc phải mua trọn gói nếu muốn mở tài khoản số miễn phí"},{"id":"B","text":"Không hề ép buộc — anh/chị hoàn toàn có quyền tuỳ chỉnh, bỏ bớt phần không phù hợp, mình chỉ đề xuất dựa trên đúng nhu cầu đã trao đổi"},{"id":"C","text":"Sản phẩm đơn lẻ luôn đắt hơn nên mua combo sẽ rẻ hơn dù không cần thiết"},{"id":"D","text":"Đây là chương trình bắt buộc của ngân hàng dành cho mọi khách hàng"}]'::jsonb, 'B', 'Câu trả lời chuẩn khẳng định tính tự nguyện, quyền tuỳ chỉnh của khách hàng và cơ sở đề xuất dựa trên nhu cầu thực tế, giúp giảm sức ép tâm lý.'),
('1.5', 3, 'Khách hàng nói: ''Tôi đã có sản phẩm đầu tư ở nơi khác rồi.'' Hành động khai thác insight tiếp theo nào là đúng quy trình xử lý phản đối?', '[{"id":"A","text":"Ngay lập tức gửi hồ sơ đầu tư mới để khách xem qua"},{"id":"B","text":"Chê nhẹ sản phẩm hiện tại của khách kém hiệu quả"},{"id":"C","text":"Hỏi: ''Vậy sản phẩm hiện tại anh/chị đang hài lòng nhất ở điểm nào?'' để tìm điểm khác biệt và liên kết với tài khoản đang dùng"},{"id":"D","text":"Kết luận ngay rằng khách không có nhu cầu và dừng cuộc gọi"}]'::jsonb, 'C', 'Việc hỏi về điểm hài lòng giúp khai thác insight, từ đó nhân viên có thể chỉ ra sự khác biệt hoặc lợi ích bổ sung khi liên kết với hệ sinh thái ngân hàng.'),
('1.5', 4, 'Trong tình huống đặc thù này, nếu khách hàng đã nói ''không'' trước đó nhưng bạn vẫn nhắc lại, cách xử lý đúng theo Objection bank riêng là gì?', '[{"id":"A","text":"Kiên nhẫn giải thích lại 3-4 lần để khách thay đổi quyết định"},{"id":"B","text":"Xin lỗi nhẹ nhàng, xác nhận lại đúng nhu cầu ban đầu, chỉ đề cập 1 lần duy nhất rồi dừng nếu khách từ chối"},{"id":"C","text":"Đề nghị khách hàng gọi lại sau 1 tuần để cân nhắc kỹ hơn"},{"id":"D","text":"Chuyển sang tư vấn một sản phẩm bảo hiểm đơn lẻ khác ngay lập tức"}]'::jsonb, 'B', 'Quy tắc ứng xử với khách đã từ chối là tôn trọng quyết định, chỉ nhắc nhở nhẹ nhàng một lần để xác nhận thông tin, sau đó dừng lại để giữ thiện cảm.'),
('1.5', 5, 'Khách hàng yêu cầu: ''Tôi cần thời gian suy nghĩ, việc này lớn quá.'' Phản hồi chuẩn của nhân viên nên là gì?', '[{"id":"A","text":"Khuyên khách hàng nên quyết định ngay vì ưu đãi chỉ có trong hôm nay"},{"id":"B","text":"Yêu cầu khách hàng cung cấp thông tin thu nhập trước khi suy nghĩ"},{"id":"C","text":"Hoàn toàn tôn trọng — có thể gửi tài liệu tham khảo chi tiết và hẹn trao đổi lại vào thời điểm anh/chị thuận tiện hơn"},{"id":"D","text":"Thông báo rằng nếu không quyết định ngay thì sẽ mất quyền lợi miễn phí tài khoản"}]'::jsonb, 'C', 'Thể hiện sự tôn trọng quyết định của khách hàng, chủ động hỗ trợ bằng tài liệu tham khảo và để ngỏ cơ hội gặp lại vào thời điểm phù hợp.'),
('2.1', 1, 'Điều kiện tối thiểu để mở sổ tiết kiệm online tại MSB là gì?', '[{"id":"A","text":"Có tài khoản thanh toán MSB và số tiền gửi từ 1.000.000đ"},{"id":"B","text":"Là khách hàng VIP và số tiền gửi từ 10.000.000đ"},{"id":"C","text":"Có tài khoản thanh toán bất kỳ ngân hàng nào và số tiền từ 500.000đ"},{"id":"D","text":"Phải ra quầy giao dịch để ký hợp đồng và số tiền từ 2.000.000đ"}]'::jsonb, 'A', 'Theo điều kiện cơ bản, khách hàng cần có tài khoản thanh toán MSB và số tiền gửi tối thiểu là 1.000.000đ.'),
('2.1', 2, 'Khi khách hàng nghi ngờ mức lãi suất cao hơn chỉ là chiêu trò quảng cáo, bạn sẽ phản hồi thế nào?', '[{"id":"A","text":"Khẳng định đây là chính sách chính thức của ngân hàng, khách có thể xem bảng lãi suất minh bạch trong app theo thời gian thực."},{"id":"B","text":"Nói rằng lãi suất này chỉ áp dụng cho những khách hàng thân thiết lâu năm."},{"id":"C","text":"Giải thích rằng lãi suất cao hơn do ngân hàng đang trợ giá tạm thời nên không ổn định."},{"id":"D","text":"Đề nghị khách hàng ra quầy để nhân viên xác nhận thủ công vì thông tin online chưa được cập nhật."}]'::jsonb, 'A', 'Câu trả lời chuẩn nhấn mạnh tính minh bạch và chính thức của lãi suất online, có thể kiểm chứng trực tiếp trên ứng dụng.'),
('2.1', 3, 'Khách hàng lo lắng về an toàn khi gửi tiền online, sợ bị mất tiền nếu gặp sự cố kỹ thuật. Câu trả lời đúng nhất là gì?', '[{"id":"A","text":"Tiền gửi được bảo hiểm theo quy định của Nhà nước và sổ tiết kiệm điện tử có giá trị pháp lý tương đương sổ giấy."},{"id":"B","text":"Ngân hàng sẽ chịu trách nhiệm hoàn toàn nhưng cần khách hàng mua thêm gói bảo hiểm riêng."},{"id":"C","text":"Gửi online an toàn hơn vì không cần giữ giấy tờ physical, nên ít rủi ro mất mát vật lý hơn."},{"id":"D","text":"Chỉ an toàn khi khách hàng sử dụng mạng WiFi riêng và không chia sẻ mật khẩu cho ai."}]'::jsonb, 'A', 'Điểm bán hàng quan trọng là sự an toàn tuyệt đối nhờ bảo hiểm tiền gửi của NHNN và giá trị pháp lý đầy đủ của sổ điện tử.'),
('2.1', 4, 'Một nhân viên văn phòng trẻ hỏi: ''Nếu lỡ tháng đó cần dùng tiền gấp thì rút trước hạn có bị mất hết lãi không?'' Bạn giải thích sao?', '[{"id":"A","text":"Không mất hết — phần tiền gửi đủ kỳ hạn tối thiểu vẫn được tính lãi không kỳ hạn, không bị mất trắng như trước đây."},{"id":"B","text":"Rút trước hạn sẽ bị phạt phí và chuyển sang lãi suất 0% cho toàn bộ số tiền đã gửi."},{"id":"C","text":"Khách hàng phải đợi đến ngày đáo hạn mới được rút, nếu rút sớm sẽ không nhận được lãi suất nào."},{"id":"D","text":"Ngân hàng sẽ miễn phí rút tiền nhưng lãi suất vẫn được tính theo kỳ hạn ban đầu dù rút sớm."}]'::jsonb, 'A', 'Đây là lợi thế cạnh tranh lớn: linh hoạt rút trước hạn mà không bị mất trắng lãi suất, chỉ tính lãi không kỳ hạn cho phần thỏa mãn điều kiện.'),
('2.1', 5, 'Khách hàng ngại thao tác vì ''không rành công nghệ''. Bạn sẽ xử lý tình huống này bằng cách nào?', '[{"id":"A","text":"Thao tác chỉ gồm 3 bước đơn giản, có hướng dẫn từng bước trong app và luôn có tổng đài hỗ trợ nếu cần."},{"id":"B","text":"Đề nghị khách hàng nhờ con cái hoặc người thân giúp đỡ vì đây là tính năng phức tạp."},{"id":"C","text":"Hứa hẹn sẽ gọi điện cho khách hàng để đăng ký hộ thay vì để khách tự làm trên app."},{"id":"D","text":"Nhấn mạnh rằng chỉ những người am hiểu công nghệ mới được phép sử dụng tính năng này."}]'::jsonb, 'A', 'Nhấn mạnh vào sự dễ dàng (3 bước), hỗ trợ hướng dẫn tích hợp trong app và kênh hỗ trợ con người để xóa bỏ rào cản tâm lý.'),
('2.2', 1, 'Khi khách hàng lo lắng về việc dễ rơi vào nợ nần do sử dụng thẻ tín dụng, bạn nên giải thích như thế nào để trấn an họ?', '[{"id":"A","text":"Khách hàng cần tự giác ghi chép sổ tay để theo dõi chi tiêu mỗi ngày."},{"id":"B","text":"App có công cụ theo dõi chi tiêu thời gian thực, cho phép đặt hạn mức cảnh báo và cấp hạn mức dựa trên thu nhập thực tế."},{"id":"C","text":"Ngân hàng sẽ tự động cắt giảm hạn mức nếu khách hàng chậm thanh toán bất kỳ khoản nào."},{"id":"D","text":"Thẻ tín dụng chỉ dành cho người có kinh nghiệm tài chính, không phù hợp với nhân viên văn phòng trẻ."}]'::jsonb, 'B', 'Phương án này nhấn mạnh các tính năng kiểm soát rủi ro trong app và nguyên tắc cấp hạn mức dựa trên năng lực tài chính của khách hàng.'),
('2.2', 2, 'Một khách hàng 25 tuổi hỏi: ''Phí thường niên có đáng không?'' so với lợi ích họ nhận được. Bạn sẽ trả lời thế nào?', '[{"id":"A","text":"Phí thường niên rất cao và không được miễn在任何 trường hợp nào."},{"id":"B","text":"Miễn phí hoàn toàn năm đầu, các năm sau miễn nếu đạt doanh số tối thiểu, giúp tổng giá trị hoàn tiền/tích điểm lớn hơn mức phí phải đóng."},{"id":"C","text":"Chỉ miễn phí năm đầu nếu khách hàng cam kết chi tiêu tối thiểu 50 triệu/năm."},{"id":"D","text":"Khách hàng nên sử dụng thẻ ghi nợ thay vì thẻ tín dụng để tránh mọi loại phí."}]'::jsonb, 'B', 'Câu trả lời đúng tập trung vào việc so sánh lợi ích (hoàn tiền/tích điểm) vượt trội so với phí thường niên, đồng thời nêu rõ điều kiện miễn phí năm sau.'),
('2.2', 3, 'Khách hàng nói: ''Tôi đã có thẻ tín dụng của ngân hàng khác rồi.'' Hành động nào là phù hợp nhất theo quy trình xử lý phản đối?', '[{"id":"A","text":"Ngừng cuộc gọi vì khách hàng đã có sản phẩm tương tự."},{"id":"B","text":"So sánh ngay lập tức lãi suất thấp hơn của ngân hàng chúng ta."},{"id":"C","text":"Hỏi xem thẻ hiện tại còn thiếu ưu đãi gì, sau đó khai thác nhu cầu và so sánh điểm khác biệt về hoàn tiền/tích điểm."},{"id":"D","text":"Yêu cầu khách hàng hủy thẻ cũ và sang mở thẻ mới ngay lập tức để nhận quà tặng."}]'::jsonb, 'C', 'Chiến lược đúng là khai thác nhu cầu bằng cách tìm ra điểm yếu của thẻ hiện tại, sau đó làm nổi bật lợi thế cạnh tranh về ưu đãi của thẻ mới.'),
('2.2', 4, 'Bạn đang tư vấn cho một nhân viên văn phòng muốn mở thẻ nhanh. Quy trình và điều kiện cơ bản là gì?', '[{"id":"A","text":"Đến trực tiếp chi nhánh, nộp hồ sơ giấy và chờ duyệt trong 3-5 ngày làm việc."},{"id":"B","text":"Mở thẻ qua app, cần chứng minh thu nhập bằng lương chuyển khoản hoặc hợp đồng lao động, thời gian duyệt vài phút."},{"id":"C","text":"Chỉ cần dùng CCCD để đăng ký, không cần chứng minh thu nhập và duyệt ngay lập tức."},{"id":"D","text":"Cần có người bảo lãnh và kê khai tài sản thế chấp để mở thẻ qua ứng dụng."}]'::jsonb, 'B', 'Quy trình đúng là hoàn toàn kỹ thuật số qua app, yêu cầu chứng minh thu nhập cơ bản và thời gian phê duyệt cực nhanh.'),
('2.2', 5, 'Ưu điểm về thời gian miễn lãi của sản phẩm thẻ tín dụng quốc tế này là bao nhiêu?', '[{"id":"A","text":"30 ngày kể từ ngày sao kê."},{"id":"B","text":"Không có thời gian miễn lãi, phải trả全额 ngay khi sử dụng."},{"id":"C","text":"45–55 ngày kể từ ngày giao dịch."},{"id":"D","text":"60 ngày nhưng chỉ áp dụng cho giao dịch rút tiền mặt."}]'::jsonb, 'C', 'Đây là key selling point quan trọng về lợi ích tài chính ngắn hạn mà khách hàng cần nắm vững khi tư vấn.'),
('2.3', 1, 'Khách hàng trẻ tuổi (24-32 tuổi) lo ngại rằng việc xin mở hạn mức vay tiêu dùng tín chấp sẽ ảnh hưởng xấu đến điểm tín dụng của họ. Nhân viên nên phản hồi như thế nào?', '[{"id":"A","text":"Việc tra cứu hồ sơ để xin mở hạn mức không làm giảm điểm tín dụng, đây chỉ là thao tác dự phòng và khách hàng có thể giữ liên hệ khi cần."},{"id":"B","text":"Mọi lần tra cứu thông tin tài chính đều bị trừ điểm tín dụng mạnh, vì vậy nhân viên khuyên khách hàng chỉ nên vay khi thực sự cần tiền gấp."},{"id":"C","text":"Để tránh ảnh hưởng điểm tín dụng, khách hàng phải cung cấp tài sản đảm bảo thay vì vay tín chấp, mặc dù điều này trái với chính sách sản phẩm."},{"id":"D","text":"Điểm tín dụng chỉ bị ảnh hưởng nếu khách hàng từ chối vay, còn việc đăng ký mở hạn mức sẽ được coi là một hành vi tích cực."}]'::jsonb, 'A', 'Trả lời trung thực và ngắn gọn: Mở hạn mức tín chấp là dịch vụ dự phòng, không giống như khoản vay phát sinh ghi nợ, nên không ảnh hưởng tiêu cực đến điểm tín dụng nếu không sử dụng.'),
('2.3', 2, 'Một nhân viên văn phòng 28 tuổi phàn nàn rằng ''Lãi suất vay tiêu dùng thường cao lắm''. Câu trả lời chuẩn xác nhất theo quy định sản phẩm là gì?', '[{"id":"A","text":"Lãi suất cố định 20%/năm cho tất cả khách hàng, thấp hơn lãi suất đen nhưng vẫn cao hơn gửi tiết kiệm."},{"id":"B","text":"Mức lãi suất cụ thể phụ thuộc vào hồ sơ từng người, nhưng vẫn thấp hơn nhiều so với vay nóng bên ngoài và hoàn toàn minh bạch ngay từ đầu."},{"id":"C","text":"Chúng tôi miễn phí lãi suất trong 6 tháng đầu, sau đó mới tính lãi, giúp khách hàng tiết kiệm chi phí ban đầu."},{"id":"D","text":"Lãi suất thấp nhất dành riêng cho khách hàng có tài sản thế chấp, còn khách hàng tín chấp sẽ chịu mức lãi suất cao nhất thị trường."}]'::jsonb, 'B', 'Câu trả lời nhấn mạnh tính minh bạch, sự linh hoạt dựa trên hồ sơ và lợi thế cạnh tranh so với các kênh vay ngoài hợp pháp.'),
('2.3', 3, 'Khách hàng tỏ ra e ngại về quy trình xử lý, cho rằng ''Thủ tục vay có phức tạp, mất nhiều thời gian không?''. Điểm bán hàng cốt lõi (Key Selling Point) nào cần được nhấn mạnh?', '[{"id":"A","text":"Hồ sơ đơn giản, xét duyệt hoàn toàn online, có thể giải ngân ngay trong ngày nếu hồ sơ đầy đủ."},{"id":"B","text":"Khách hàng cần trực tiếp đến chi nhánh để ký kết giấy tờ và chờ đợi 7-14 ngày làm việc để phê duyệt."},{"id":"C","text":"Nhân viên sẽ hỗ trợ điền hồ sơ tại nhà, nhưng quá trình xét duyệt vẫn cần sự phê duyệt thủ công của hội đồng tín dụng."},{"id":"D","text":"Quy trình phức tạp hơn do không có tài sản đảm bảo, đòi hỏi khách hàng cung cấp thêm nhiều loại giấy tờ chứng minh thu nhập."}]'::jsonb, 'A', 'Nhấn mạnh vào trải nghiệm khách hàng: Đơn giản hóa quy trình qua kênh số (online) và tốc độ giải ngân nhanh chóng.'),
('2.3', 4, 'Khi khách hàng nói ''Tôi sợ không trả nợ đúng hạn'', chiến lược tư vấn nào phù hợp với phương án xử lý phản đối đã định sẵn?', '[{"id":"A","text":"Khuyên khách hàng vay số tiền nhỏ nhất có thể để giảm áp lực trả góp hàng tháng."},{"id":"B","text":"Cùng tính toán số tiền trả góp phù hợp với thu nhập trước khi quyết định vay, chọn kỳ hạn sao cho khoản trả hàng tháng thoải mái nhất."},{"id":"C","text":"Giải thích rằng phạt chậm trả không quá nghiêm trọng và khách hàng chỉ cần nhớ thanh toán mỗi năm một lần."},{"id":"D","text":"Đề nghị khách hàng vay thêm một khoản khác để trang trải khoản hiện tại, nhằm kéo dài thời gian trả nợ."}]'::jsonb, 'B', 'Tập trung vào giải pháp thực tế: Cùng khách hàng phân tích tài chính để lựa chọn kỳ hạn và mức vay an toàn, phù hợp khả năng chi trả.'),
('2.3', 5, 'Khách hàng khẳng định ''Tôi chưa có nhu cầu vay ngay bây giờ''. Hành động chăm sóc khách hàng nào là đúng chuẩn?', '[{"id":"A","text":"Gác máy ngay lập tức để tránh làm phiền khách hàng đang bận rộn."},{"id":"B","text":"Kiên nhẫn giới thiệu các ưu đãi giảm giá cho sản phẩm thẻ tín dụng thay vì vay tiêu dùng."},{"id":"C","text":"Không sao, có thể giữ liên hệ và giới thiệu một hạn mức vay dự phòng sẵn có, khi nào cần chỉ cần thao tác trên app."},{"id":"D","text":"Yêu cầu khách hàng cam kết sẽ vay trong vòng 3 tháng tới để được giữ ưu đãi lãi suất đặc biệt."}]'::jsonb, 'C', 'Giữ kết nối mà không gây áp lực: Biến từ chối tạm thời thành cơ hội tạo dựng quan hệ dài hạn bằng cách đề xuất hạn mức dự phòng linh hoạt.'),
('2.4', 1, 'Khách hàng trẻ tuổi (24-32) lo ngại rằng tham gia bảo hiểm liên kết đầu tư sẽ làm giảm ngân sách cho các hoạt động giải trí như du lịch. Bạn sẽ phản hồi thế nào theo nguyên tắc đã định?', '[{"id":"A","text":"Từ chối yêu cầu của khách vì đây là sản phẩm dài hạn, không phù hợp với nhu cầu trước mắt."},{"id":"B","text":"Đề nghị khách hủy bỏ kế hoạch du lịch để tập trung hoàn toàn vào tích lũy tài chính."},{"id":"C","text":"Giải thích rằng có thể điều chỉnh mức phí rất nhỏ, đảm bảo không ảnh hưởng đến ngân sách du lịch hiện tại của khách."},{"id":"D","text":"Khuyến khích khách vay thêm tiền để đóng phí cao hơn nhằm tăng quyền lợi đầu tư."}]'::jsonb, 'C', 'Theo objection bank riêng cho tình huống này, cần không phủ nhận nhu cầu hưởng thụ mà đề xuất mức phí nhỏ không ảnh hưởng ngân sách du lịch.'),
('2.4', 2, 'Khi khách hàng hỏi: ''Tôi còn trẻ, chưa cần bảo hiểm'', câu trả lời chuẩn xác nhất theo key selling points là gì?', '[{"id":"A","text":"Khách hàng nên đợi đến khi lập gia đình hoặc có con thì mới cần mua bảo hiểm."},{"id":"B","text":"Tham gia càng sớm, mức phí càng thấp và thời gian tích lũy càng dài, đây là thời điểm tối ưu nhất."},{"id":"C","text":"Bảo hiểm chỉ dành cho người lớn tuổi, nhân viên văn phòng trẻ không nên quan tâm."},{"id":"D","text":"Phí bảo hiểm sẽ giảm dần nếu khách chờ đợi thêm vài năm nữa để tham gia."}]'::jsonb, 'B', 'Key selling point nhấn mạnh lợi ích của việc tham gia sớm: phí thấp hơn và thời gian tích lũy dài hơn, làm cơ sở cho lời khuyên này.'),
('2.4', 3, 'Khách hàng lo lắng nghe nhiều tin tức về việc tư vấn sai lệch khiến họ không rút được tiền sau khi đóng bảo hiểm. Phương án trả lời chuẩn là gì?', '[{"id":"A","text":"Cam kết chắc chắn 100% rằng khách sẽ luôn có lãi cao hơn gửi tiết kiệm."},{"id":"B","text":"Bỏ qua lo lắng này vì hợp đồng đã ký kết thì không thể thay đổi."},{"id":"C","text":"Lý do khách không rút được tiền là do họ không hiểu rõ sản phẩm, không phải do tư vấn sai."},{"id":"D","text":"Chia sẻ sự thấu cảm, cam kết đọc kỹ điều khoản trước khi ký và nhắc nhở về quyền cân nhắc/hủy trong 21 ngày đầu."}]'::jsonb, 'D', 'Câu trả lời chuẩn xử lý nỗi đau tâm lý bằng sự thấu cảm, minh bạch quy trình và đặc biệt nhấn mạnh quyền lợi ''thời gian cân nhắc'' 21 ngày.'),
('2.4', 4, 'Khách hàng băn khoăn: ''Bảo hiểm liên kết đầu tư có rủi ro mất tiền không?''. Nội dung nào dưới đây là câu trả lời đúng chuẩn?', '[{"id":"A","text":"Không bao giờ mất tiền vì ngân hàng bảo lãnh toàn bộ số vốn."},{"id":"B","text":"Sản phẩm gồm phần bảo vệ cố định và phần đầu tư với các mức rủi ro khác nhau, mọi thông tin đều minh bạch trong hợp đồng."},{"id":"C","text":"Rủi ro là không tránh khỏi nhưng nhân viên sẽ chịu trách nhiệm bù đắp nếu bị lỗ."},{"id":"D","text":"Phần đầu tư luôn sinh lời ổn định nên khách hoàn toàn yên tâm về an toàn vốn."}]'::jsonb, 'B', 'Câu trả lời chuẩn cần làm rõ cấu trúc 2 phần (bảo vệ cố định và đầu tư linh hoạt) và tính minh bạch thông tin, tránh hứa hẹn chắc ăn.'),
('2.4', 5, 'Nếu khách hàng cho rằng ''Phí đóng hàng năm cao quá, tôi không đủ khả năng chi trả'', bạn sẽ đưa ra giải pháp nào?', '[{"id":"A","text":"Khuyên khách chọn gói bảo hiểm rẻ nhất nhưng không có phần đầu tư."},{"id":"B","text":"Giới thiệu các sản phẩm bảo hiểm ngắn hạn một lần để giảm tải áp lực phí."},{"id":"C","text":"Yêu cầu khách vay ngân hàng để đóng phí trọn gói cho cả 20 năm."},{"id":"D","text":"Gợi ý điều chỉnh mức phí phù hợp với thu nhập hiện tại, không nhất thiết chọn gói cao nhất ngay từ đầu."}]'::jsonb, 'D', 'Objection bank chỉ ra rằng phí có thể linh hoạt điều chỉnh theo thu nhập, giúp khách bắt đầu ở mức độ phù hợp thay vì từ chối ngay.'),
('2.5', 1, 'Khách hàng là nhân viên văn phòng trẻ (24-32 tuổi) hỏi: ''Tôi chỉ cần 1 sản phẩm thôi, sao phải mua combo?''. Câu trả lời chuẩn nào sau đây là phù hợp nhất theo ngân hàng phản đối?', '[{"id":"A","text":"Combo bắt buộc phải mua trọn gói nên anh/chị vui lòng cân nhắc kỹ."},{"id":"B","text":"Hoàn toàn hiểu — combo không bắt buộc trọn gói, mỗi phần đều là sản phẩm độc lập hữu ích, chỉ là khi kết hợp sẽ tiết kiệm chi phí hơn đáng kể."},{"id":"C","text":"Anh/chị trẻ nên đầu tư đa dạng, mua lẻ sẽ rất tốn phí và phức tạp quản lý."},{"id":"D","text":"Combo này đang có chương trình khuyến mãi lớn, nếu không mua thì bỏ lỡ ưu đãi độc quyền."}]'::jsonb, 'B', 'Câu trả lời đúng nhấn mạnh tính linh hoạt (không ép mua trọn gói) và lợi ích cốt lõi về mặt chi phí khi kết hợp các sản phẩm độc lập.'),
('2.5', 2, 'Khi khách hàng lo lắng rằng ''Nghe combo là thấy bị ép mua thêm cái không cần'', nhân viên nên phản hồi thế nào để tạo sự tin tưởng?', '[{"id":"A","text":"Không hề ép buộc — anh/chị hoàn toàn có quyền tuỳ chỉnh, bỏ bớt phần không phù hợp, mình chỉ đề xuất dựa trên đúng nhu cầu đã trao đổi."},{"id":"B","text":"Combo là giải pháp tối ưu nhất nên anh/chị không cần lo lắng về việc dư thừa sản phẩm."},{"id":"C","text":"Việc bán combo giúp ngân hàng hỗ trợ anh/chị tốt hơn, nên anh/chị hãy tin tưởng vào chuyên môn của chúng tôi."},{"id":"D","text":"Thực tế nhiều khách hàng cũng cảm thấy bị ép ban đầu, nhưng sau đó họ đều hài lòng vì tiện lợi."}]'::jsonb, 'A', 'Câu trả lời đúng khẳng định quyền tự chủ của khách hàng trong việc tuỳ chỉnh sản phẩm và liên kết trực tiếp với nhu cầu thực tế đã thảo luận.'),
('2.5', 3, 'Khách hàng nói: ''Tôi đã có sản phẩm đầu tư ở nơi khác rồi''. Bước đầu tiên nhân viên nên làm gì theo quy trình xử lý phản đối này?', '[{"id":"A","text":"Ngay lập tức liệt kê tất cả các ưu điểm của quỹ mở/chứng chỉ quỹ tại ngân hàng để chứng minh sản phẩm mới tốt hơn."},{"id":"B","text":"Đề nghị khách hàng đóng tài khoản cũ để chuyển toàn bộ sang ngân hàng hiện tại nhằm tận dụng ưu đãi độc quyền."},{"id":"C","text":"Hỏi: ''Vậy sản phẩm hiện tại anh/chị đang hài lòng nhất ở điểm nào?'' để khai thác insight trước khi chỉ ra điểm khác biệt."},{"id":"D","text":"Chấp nhận ngay rằng khách hàng không cần sản phẩm đầu tư nữa và chuyển sang tư vấn bảo hiểm hoặc tài khoản số."}]'::jsonb, 'C', 'Theo bank phản đối, việc đầu tiên là khai thác insight (điểm hài lòng của khách với sản phẩm cũ) để tìm ra cơ hội so sánh và chỉ ra sự liên kết độc đáo của combo.'),
('2.5', 4, 'Nếu khách hàng hỏi về điều kiện ràng buộc hoặc khả năng huỷ giữa chừng của Combo (Tài khoản số + Bảo hiểm + Đầu tư), nhân viên cần đảm bảo điều gì?', '[{"id":"A","text":"Nhấn mạnh rằng combo không bao giờ được phép huỷ vì đã cam kết lợi ích dài hạn cho khách hàng."},{"id":"B","text":"Trả lời rõ ràng, không giấu điều khoản, cung cấp thông tin chính xác về quyền lợi huỷ/giải nén sản phẩm."},{"id":"C","text":"Tránh đề cập chi tiết điều khoản huỷ mà tập trung vào các ưu đãi độc quyền để giữ chân khách hàng."},{"id":"D","text":"Bảo đảm rằng mọi chi phí đã đóng sẽ được hoàn lại 100% bất kể lý do huỷ từ phía khách hàng."}]'::jsonb, 'B', 'Đối với tình huống riêng này, nguyên tắc là phải minh bạch, trả lời rõ ràng và không che giấu điều khoản để xây dựng niềm tin lâu dài.'),
('2.5', 5, 'Đâu là Key Selling Point (USP) chính của Combo tích hợp này so với việc mua lẻ từng sản phẩm?', '[{"id":"A","text":"Combo chỉ dành cho khách hàng có thu nhập thấp để dễ dàng tiếp cận dịch vụ ngân hàng."},{"id":"B","text":"Giải pháp tài chính toàn diện, tiết kiệm chi phí tổng thể và không phải chắp vá từng phần riêng lẻ."},{"id":"C","text":"Combo bắt buộc phải bao gồm cả ba thành phần Tài khoản, Bảo hiểm và Đầu tư với tỷ lệ cố định."},{"id":"D","text":"Sản phẩm đầu tư trong combo luôn mang lại lợi nhuận cao nhất thị trường bất chấp rủi ro."}]'::jsonb, 'B', 'USP cốt lõi là tính toàn diện (toàn diện hóa tài chính), sự tiện lợi (không chắp vá) và hiệu quả kinh tế (tiết kiệm chi phí) nhờ việc tích hợp các sản phẩm độc lập.'),
('3.1', 1, 'Điều kiện nào sau đây là bắt buộc để khách hàng có thể gửi tiết kiệm online tại MSB?', '[{"id":"A","text":"Phải có sổ hộ khẩu và giấy tờ tùy thân mang đến chi nhánh"},{"id":"B","text":"Chỉ dành cho khách hàng doanh nghiệp với số dư tối thiểu 10 triệu đồng"},{"id":"C","text":"Có tài khoản thanh toán MSB và số tiền gửi tối thiểu từ 1.000.000đ"},{"id":"D","text":"Phải ký hợp đồng trực tiếp với trưởng phòng kinh doanh"}]'::jsonb, 'C', 'Theo điều kiện cơ bản, khách hàng cần có tài khoản thanh toán MSB và thực hiện gửi từ 1 triệu đồng trở lên qua app.'),
('3.1', 2, 'Khi khách hàng lo lắng về sự an toàn của tiền gửi online, nhân viên nên trả lời chính xác như thế nào?', '[{"id":"A","text":"Tiền gửi online chỉ được bảo vệ bởi ngân hàng, không có bảo hiểm nhà nước"},{"id":"B","text":"Gửi online an toàn tương đương tại quầy, tiền được bảo hiểm theo quy định NHNN và sổ điện tử có giá trị pháp lý như sổ giấy"},{"id":"C","text":"Khách hàng nên in ra giấy để đảm bảo an toàn tuyệt đối hơn"},{"id":"D","text":"Ngân hàng cam kết bồi thường gấp đôi nếu xảy ra sự cố kỹ thuật"}]'::jsonb, 'B', 'Câu trả lời chuẩn nhấn mạnh tính bảo hiểm theo quy định Nhà nước và giá trị pháp lý tương đương của sổ tiết kiệm điện tử.'),
('3.1', 3, 'Nếu khách hàng hỏi về việc rút trước hạn có bị mất hết lãi hay không, nhân viên cần giải thích gì?', '[{"id":"A","text":"Mất trắng toàn bộ lãi suất đã accrual kể từ ngày đầu gửi"},{"id":"B","text":"Không mất hết — phần tiền đủ kỳ hạn tối thiểu vẫn được tính lãi không kỳ hạn, không bị mất trắng"},{"id":"C","text":"Chỉ được hoàn vốn gốc, không nhận bất kỳ khoản lãi nào dù chỉ 1 ngày"},{"id":"D","text":"Phải chịu phạt 5% giá trị tiền gửi nếu rút trước hạn"}]'::jsonb, 'B', 'Điểm bán hàng quan trọng là tính linh hoạt: rút trước hạn không mất hết lãi, phần đủ kỳ hạn tối thiểu vẫn tính lãi không kỳ hạn.'),
('3.1', 4, 'Khách hàng nghi ngờ mức lãi suất cao trên app so với bảng niêm yết tại quầy, nhân viên sẽ xử lý thế nào?', '[{"id":"A","text":"Khẳng định đây là lỗi hệ thống và yêu cầu khách chờ cập nhật lại sau"},{"id":"B","text":"Đây là chính sách chính thức, minh bạch, khách có thể xem trực tiếp bảng lãi suất trong app cập nhật thời gian thực"},{"id":"C","text":"Lãi suất cao hơn chỉ áp dụng cho khách hàng VIP chứ không phải đại chúng"},{"id":"D","text":"Khuyến nghị khách ra quầy để được tư vấn mức lãi suất cố định ổn định hơn"}]'::jsonb, 'B', 'Trả lời chuẩn khẳng định tính chính thức và minh bạch của chính sách, hướng khách hàng kiểm tra trực tiếp trên app để thấy lãi suất cập nhật thực tế.'),
('3.1', 5, 'Đối với khách hàng là chủ hộ kinh doanh phàn nàn rằng ''Ngân hàng X trả lãi cao hơn 0.3%'', nhân viên nên phản hồi ra sao?', '[{"id":"A","text":"Đồng ý ngay lập tức và đề xuất chuyển tiền sang ngân hàng khác"},{"id":"B","text":"Từ chối nói chuyện vì đây là tin đồn thất thiệt"},{"id":"C","text":"Thừa nhận nếu đúng, nhưng đưa ra điểm bù lại như sự linh hoạt, dịch vụ hỗ trợ nhanh chóng và thao tác đơn giản trên app"},{"id":"D","text":"Yêu cầu khách cung cấp bằng chứng ghi âm mới có thể cân nhắc giảm lãi suất"}]'::jsonb, 'C', 'Chiến lược xử lý phản đối riêng cho tình huống này là thừa nhận sự chênh lệch (nếu có) và đánh vào các yếu tố phi lãi suất như tiện ích, tốc độ và sự linh hoạt.'),
('3.2', 1, 'Nhân viên cần xác minh những điều kiện cơ bản nào để khách hàng đủ điều kiện mở thẻ tín dụng quốc tế?', '[{"id":"A","text":"Khách hàng phải có tài sản thế chấp là nhà đất hoặc ô tô."},{"id":"B","text":"Khách hàng từ đủ 18 tuổi và chứng minh được thu nhập qua lương chuyển khoản hoặc hợp đồng lao động."},{"id":"C","text":"Khách hàng phải có số dư tài khoản tiết kiệm tối thiểu 50 triệu đồng."},{"id":"D","text":"Khách hàng phải có lịch sử tín dụng tốt tại tất cả các ngân hàng khác."}]'::jsonb, 'B', 'Điều kiện cơ bản bao gồm độ tuổi từ đủ 18 và khả năng chứng minh thu nhập, không yêu cầu tài sản thế chấp hay số dư tiết kiệm.'),
('3.2', 2, 'Khi khách hàng là chủ hộ kinh doanh lo lắng ''lỡ dùng quá tay ảnh hưởng dòng tiền kinh doanh'', nhân viên nên phản hồi như thế nào?', '[{"id":"A","text":"Khuyên khách hàng chỉ nên vay vốn dài hạn cho kinh doanh để đảm bảo an toàn."},{"id":"B","text":"Đề xuất hạn mức cao nhất có thể để khách hàng linh hoạt trong mọi tình huống mua sắm."},{"id":"C","text":"Đề xuất hạn mức phù hợp với quy mô kinh doanh thực tế, không khuyến nghị hạn mức quá cao so khả năng chi trả."},{"id":"D","text":"Từ chối cấp thẻ vì đối tượng kinh doanh nhỏ lẻ luôn có rủi ro thanh toán cao."}]'::jsonb, 'C', 'Giải pháp đúng là cân nhắc hạn mức phù hợp với quy mô kinh doanh để kiểm soát rủi ro dòng tiền, tránh đề xuất hạn mức vượt quá khả năng.'),
('3.2', 3, 'Câu trả lời chuẩn nào sau đây là chính xác khi khách hàng hỏi về phí thường niên của thẻ?', '[{"id":"A","text":"Phí thường niên luôn cố định 1 triệu đồng/năm cho tất cả các năm."},{"id":"B","text":"Miễn phí hoàn toàn năm đầu, các năm sau miễn nếu đạt doanh số chi tiêu tối thiểu theo chính sách."},{"id":"C","text":"Miễn phí năm đầu, nhưng các năm sau sẽ tự động trừ vào tài khoản thanh toán."},{"id":"D","text":"Khách hàng phải đóng phí thường niên trước khi được kích hoạt tính năng hoàn tiền."}]'::jsonb, 'B', 'Chính sách ưu đãi là miễn phí năm đầu và miễn phí các năm tiếp theo nếu đáp ứng điều kiện doanh số chi tiêu tối thiểu.'),
('3.2', 4, 'Nếu khách hàng nói ''Tôi đã có thẻ ngân hàng khác rồi'', nhân viên应采取 hành động gì để khai thác nhu cầu?', '[{"id":"A","text":"Ngừng tư vấn ngay lập tức vì khách đã có sản phẩm tương đương."},{"id":"B","text":"So sánh ngay lập tức giá trị thấp hơn của thẻ hiện tại mà không hỏi thêm."},{"id":"C","text":"Hỏi khách đang thấy thẻ hiện tại còn thiếu ưu đãi gì, sau đó so sánh điểm khác biệt về hoàn tiền/tích điểm."},{"id":"D","text":"Yêu cầu khách hủy thẻ cũ trước khi nộp hồ sơ mở thẻ mới."}]'::jsonb, 'C', 'Chiến lược đúng là khai thác nhu cầu bằng cách tìm hiểu điểm yếu của thẻ hiện tại, sau đó nhấn mạnh lợi thế cạnh tranh về hoàn tiền/tích điểm.'),
('3.2', 5, 'Công cụ hỗ trợ nào trên App giúp giải quyết nỗi sợ ''dễ nợ nần, không kiểm soát được'' của khách hàng?', '[{"id":"A","text":"Chức năng gọi điện thoại tự động cho các nhà cung cấp dịch vụ."},{"id":"B","text":"Công cụ theo dõi chi tiêu thời gian thực và khả năng tự đặt hạn mức cảnh báo."},{"id":"C","text":"Chức năng chuyển tiền quốc tế miễn phí sang tài khoản nước ngoài."},{"id":"D","text":"Tính năng khóa thẻ vĩnh viễn mỗi khi hết ngày 30 hàng tháng."}]'::jsonb, 'B', 'App cung cấp công cụ theo dõi chi tiêu thực tế và tùy chọn đặt cảnh báo, giúp khách hàng chủ động quản lý tài chính cá nhân.'),
('3.3', 1, 'Khi khách hàng là chủ hộ kinh doanh hỏi: ''Sao lãi suất bên này cao hơn tôi tính?'', nhân viên cần làm gì để xử lý đúng?', '[{"id":"A","text":"Khuyên khách hàng vay nóng bên ngoài vì rẻ hơn"},{"id":"B","text":"Giải thích rõ cách tính lãi (dư nợ giảm dần vs cố định) và đối chiếu số liệu cụ thể để khách so sánh đúng bản chất"},{"id":"C","text":"Giảm lãi suất xuống thấp nhất có thể mà không cần giải thích gì thêm"},{"id":"D","text":"Từ chối tư vấn vì khách hàng thiếu hiểu biết về tài chính"}]'::jsonb, 'B', 'Nhân viên cần giải thích minh bạch về cơ chế tính lãi và đối chiếu số liệu thực tế để khách hàng thấy được sự tương quan, tránh hiểu lầm.'),
('3.3', 2, 'Đối với khách hàng tự kinh doanh lo ngại về việc giải ngân trễ ảnh hưởng đến lịch nhập hàng, nhân viên nên phản hồi thế nào?', '[{"id":"A","text":"Cam kết mốc thời gian cụ thể và nêu rõ các điều kiện hồ sơ cần thiết để đảm bảo đúng tiến độ"},{"id":"B","text":"Hứa hẹn giải ngân trong ngày bất kể tình trạng hồ sơ"},{"id":"C","text":"Bảo khách hàng hãy chờ đến khi có đơn đặt hàng mới gọi lại"},{"id":"D","text":"Đề nghị khách hàng dùng thẻ tín dụng thay vì vay tiêu dùng"}]'::jsonb, 'A', 'Việc cam kết mốc thời gian cụ thể kèm điều kiện rõ ràng giúp tạo niềm tin và quản lý kỳ vọng của khách hàng hiệu quả.'),
('3.3', 3, 'Nếu khách hàng nói: ''Tôi chưa có nhu cầu vay ngay bây giờ'', câu trả lời chuẩn nào sau đây là phù hợp?', '[{"id":"A","text":"Thôi vậy, cảm ơn anh/chị đã dành thời gian"},{"id":"B","text":"Yêu cầu khách hàng điền đơn xin vay trước để giữ chỗ"},{"id":"C","text":"Không sao, có thể giữ liên hệ và giới hạn mức vay dự phòng sẵn có, khi nào cần chỉ thao tác trên app"},{"id":"D","text":"Nhắc nhở khách hàng rằng nếu không vay sẽ mất ưu đãi"}]'::jsonb, 'C', 'Mục tiêu là duy trì mối quan hệ và cung cấp giải pháp dự phòng linh hoạt qua app, không gây áp lực lên khách hàng.'),
('3.3', 4, 'Khi khách hàng lo lắng ''Tôi sợ không trả nợ đúng hạn'', nhân viên nên đưa ra giải pháp nào?', '[{"id":"A","text":"Khuyến khích khách hàng vay nhiều hơn để có quỹ dự phòng"},{"id":"B","text":"Cùng tính toán số tiền trả góp phù hợp thu nhập và chọn kỳ hạn để khoản trả hàng tháng thoải mái nhất"},{"id":"C","text":"Khuyên khách hàng bán tài sản cá nhân nếu gặp khó khăn"},{"id":"D","text":"Bảo khách hàng rằng lãi suất sẽ tự động giảm nếu trả chậm"}]'::jsonb, 'B', 'Linh hoạt hóa kỳ hạn và số tiền trả góp dựa trên khả năng thực tế của khách hàng giúp giảm rủi ro vỡ nợ và tăng sự an tâm.'),
('3.3', 5, 'Điểm khác biệt cốt lõi nào của sản phẩm Vay tiêu dùng tín chấp được nhấn mạnh khi giải đáp thắc mắc về thủ tục?', '[{"id":"A","text":"Phải đến trực tiếp chi nhánh và nộp giấy tờ bản cứng"},{"id":"B","text":"Cần có người bảo lãnh uy tín mới được xét duyệt"},{"id":"C","text":"Hồ sơ đơn giản, xét duyệt online, giải ngân nhanh trong ngày nếu đầy đủ"},{"id":"D","text":"Chỉ chấp nhận khách hàng có tài sản cầm cố giá trị lớn"}]'::jsonb, 'C', 'Tính năng ''xét duyệt online'' và ''giải ngân nhanh'' là lợi thế cạnh tranh chính giúp tiết kiệm thời gian cho khách hàng tự kinh doanh.'),
('3.4', 1, 'Khách hàng là chủ hộ kinh doanh 40 tuổi, lo ngại rằng tiền đóng bảo hiểm liên kết đầu tư có thể bị mất nếu phần đầu tư thất bại. Nhân viên cần giải thích như thế nào để làm rõ cấu trúc sản phẩm?', '[{"id":"A","text":"Sản phẩm chỉ có một phần duy nhất là đầu tư nên rủi ro cao nhưng lợi nhuận cũng cao."},{"id":"B","text":"Tiền khách hàng sẽ được ngân hàng giữ an toàn tuyệt đối không chịu bất kỳ rủi ro thị trường nào."},{"id":"C","text":"Sản phẩm gồm hai phần rõ ràng: phần bảo vệ cố định và phần đầu tư với các mức rủi ro khác nhau để khách lựa chọn, mọi thông tin đều minh bạch trong hợp đồng."},{"id":"D","text":"Nếu phần đầu tư lỗ, công ty sẽ bù đắp bằng phần bảo vệ để đảm bảo khách không mất gì."}]'::jsonb, 'C', 'Câu trả lời đúng nhấn mạnh cơ chế ''2 trong 1'' và tính minh bạch về các mức rủi ro đầu tư, giúp khách hiểu rõ bản chất sản phẩm thay vì sợ hãi mù quáng.'),
('3.4', 2, 'Một chủ shop online 35 tuổi nói rằng họ từng nghe đồn về việc tư vấn sai lệch khiến khách đóng xong không rút được tiền. Phản hồi chuẩn xác nhất của nhân viên là gì?', '[{"id":"A","text":"Đó là do khách mua nhầm sản phẩm khác, còn sản phẩm của chúng tôi cam kết rút tiền ngay lập tức."},{"id":"B","text":"Chúng tôi cam kết hoàn toàn 100% không xảy ra hiện tượng tư vấn sai lệch trên thị trường."},{"id":"C","text":"Cảm ơn anh/chị đã chia sẻ, chúng ta sẽ cùng đọc kỹ điều khoản trước khi ký và anh/chị có quyền cân nhắc/hủy hợp đồng trong vòng 21 ngày đầu sau khi ký."},{"id":"D","text":"Anh/chị yên tâm, nếu không hài lòng sau này chúng tôi sẽ bồi thường gấp đôi số tiền đã đóng."}]'::jsonb, 'C', 'Câu trả lời này ghi nhận nỗi lo lắng của khách (empathy) và đưa ra giải pháp cụ thể là quyền ''thời gian cân nhắc 21 ngày'', giúp khách cảm thấy chủ động và an tâm.'),
('3.4', 3, 'Khách hàng quán ăn cho rằng phí đóng hàng năm quá cao so với dòng tiền hiện tại và muốn từ bỏ ý tưởng. Giải pháp phù hợp nhất theo quy trình bán hàng là gì?', '[{"id":"A","text":"Khuyên khách hãy vay thêm tiền ngân hàng để đóng phí nhằm giữ hồ sơ tốt."},{"id":"B","text":"Nhấn mạnh rằng đây là nghĩa vụ bắt buộc nên khách phải chấp nhận thanh toán."},{"id":"C","text":"Gợi ý điều chỉnh mức phí phù hợp với khả năng tài chính hiện tại, không nhất thiết chọn gói cao nhất ngay từ đầu."},{"id":"D","text":"Giới thiệu sản phẩm bảo hiểm ngắn hạn thay thế vì sản phẩm dài hạn quá phức tạp."}]'::jsonb, 'C', 'Giải pháp này linh hoạt, tôn trọng khả năng tài chính thực tế của khách hàng tự kinh doanh, giúp duy trì cuộc trò chuyện mà không gây áp lực.'),
('3.4', 4, 'Khách hàng 50 tuổi khẳng định: ''Tôi còn trẻ và sức khỏe tốt, chưa cần mua bảo hiểm nhân thọ lúc này''. Lập luận thuyết phục nhất để xử lý phản đối này dựa trên key selling point là gì?', '[{"id":"A","text":"Tham gia càng sớm, mức phí càng thấp và thời gian tích lũy vốn đầu tư càng dài, tạo lợi thế tối ưu cho mục tiêu tài chính tương lai."},{"id":"B","text":"Nếu không mua bây giờ, sau này bệnh viện sẽ từ chối khám chữa bệnh cho anh/chị."},{"id":"C","text":"Các khách hàng cùng trang lứa với anh/chị đều đã mua để tránh bị xã hội ostracize."},{"id":"D","text":"Bảo hiểm chỉ dành cho người già hoặc người có bệnh mãn tính, không phù hợp với người trẻ."}]'::jsonb, 'A', 'Lập luận này đánh trúng vào lợi ích ''Phí thấp hơn nếu tham gia sớm'' và ''Tích lũy dài hạn'', biến sự ''cần'' thành ''cơ hội tối ưu'' thay vì đe dọa.'),
('3.4', 5, 'Chủ hộ kinh doanh đề xuất: ''Thà để tiền này quay vòng vốn cửa hàng còn sinh lời hơn là đóng bảo hiểm''. Cách phản biện khéo léo nhất là gì?', '[{"id":"A","text":"Chứng minh rằng lãi suất ngân hàng luôn thấp hơn đầu tư vào hàng hóa."},{"id":"B","text":"Chỉ ra rằng vốn kinh doanh dùng để sinh lời, còn bảo hiểm là quỹ dự phòng rủi ro tài chính cá nhân/gia đình, mang bản chất khác biệt và bổ trợ cho nhau."},{"id":"C","text":"Nói rằng nếu cửa hàng thua lỗ thì tiền bảo hiểm cũng sẽ bị mất theo."},{"id":"D","text":"Khuyến khích khách mua nhiều giấy tờ nhà đất thay vì bảo hiểm để đầu tư an toàn hơn."}]'::jsonb, 'B', 'Câu trả lời này ghi nhận logic kinh doanh của khách nhưng phân biệt rõ bản chất giữa ''vốn đầu tư sinh lời'' và ''quỹ dự phòng rủi ro'', giúp khách thấy sản phẩm là sự bổ trợ cần thiết.'),
('3.5', 1, 'Đối với khách hàng là chủ hộ kinh doanh/tự kinh doanh (35-55 tuổi), bước quan trọng nhất trước khi đề xuất Combo (Tài khoản số + Bảo hiểm + Đầu tư) là gì?', '[{"id":"A","text":"Báo ngay mức phí tiết kiệm được so với mua lẻ để kích thích mua hàng."},{"id":"B","text":"Khai thác nhu cầu tài chính tổng thể của khách hàng để xác định các điểm chưa được bảo vệ hoặc tối ưu."},{"id":"C","text":"Đề xuất gói đầu tư chứng chỉ quỹ có rủi ro thấp nhất ngay lập tức."},{"id":"D","text":"Yêu cầu khách hàng mở tài khoản số trước rồi mới bàn về bảo hiểm và đầu tư."}]'::jsonb, 'B', 'Đây là sản phẩm khó nhất, đòi hỏi phải khai thác nhu cầu tổng thể trước để tránh cảm giác bị ép bán lẻ tẻ, từ đó mới xây dựng giải pháp tích hợp phù hợp.'),
('3.5', 2, 'Khách hàng phản đối: ''Tôi chỉ cần 1 sản phẩm thôi, sao phải mua combo?''. Câu trả lời chuẩn nào sau đây là đúng nguyên tắc xử lý phản đối?', '[{"id":"A","text":"''Combo bắt buộc phải mua trọn gói để được giảm giá sâu, anh/chị không thể chọn lẻ.''"},{"id":"B","text":"''Hiểu rồi, nhưng nếu mua lẻ sẽ rất đắt và thiếu tính liên kết. Anh/chị nên nghe thử nhé.''"},{"id":"C","text":"''Hoàn toàn hiểu — combo không bắt buộc trọn gói, mỗi phần đều độc lập hữu ích, chỉ là khi kết hợp sẽ tiết kiệm chi phí hơn đáng kể.''"},{"id":"D","text":"''Anh/chị đang dùng dịch vụ khác thì bỏ đi, sang đây mua combo rẻ hơn nhiều.''"}]'::jsonb, 'C', 'Câu trả lời này khẳng định tính linh hoạt (không ép buộc) nhưng nhấn mạnh lợi ích cốt lõi là sự tiết kiệm chi phí khi kết hợp các sản phẩm độc lập.'),
('3.5', 3, 'Khi khách hàng nói: ''Nghe combo là thấy bị ép mua thêm cái không cần.'', nhân viên nên phản hồi như thế nào để xoa dịu và duy trì cuộc trò chuyện?', '[{"id":"A","text":"''Không hề ép buộc — anh/chị hoàn toàn có quyền tuỳ chỉnh, bỏ bớt phần không phù hợp, mình chỉ đề xuất dựa trên đúng nhu cầu đã trao đổi.''"},{"id":"B","text":"''Thì em giới thiệu cho anh/chị tham khảo thôi, mua hay không là do anh/chị.''"},{"id":"C","text":"''Combo này đang có chương trình khuyến mãi đặc biệt, bỏ lỡ là tiếc lắm ạ.''"},{"id":"D","text":"''Nhiều khách hàng cũng nghĩ vậy ban đầu, nhưng họ đều hài lòng khi nhận ra lợi ích thực tế.''"}]'::jsonb, 'A', 'Câu trả lời trực tiếp xóa bỏ cảm giác bị ép buộc bằng cách khẳng định quyền tự quyết của khách hàng và gắn liền đề xuất với nhu cầu thực tế đã thảo luận.'),
('3.5', 4, 'Khách hàng nói: ''Tôi đã có sản phẩm đầu tư ở nơi khác rồi''. Hành động nào sau đây là đúng quy trình xử lý phản đối này?', '[{"id":"A","text":"Kể tên tất cả các sản phẩm đầu tư của ngân hàng để so sánh tỷ lệ lợi nhuận."},{"id":"B","text":"Đồng ý rằng sản phẩm cũ tốt hơn và chuyển sang tư vấn gói bảo hiểm đơn thuần."},{"id":"C","text":"Hỏi thăm điểm hài lòng nhất của sản phẩm hiện tại để tìm điểm khác biệt, ví dụ như khả năng liên kết trực tiếp với tài khoản đang dùng."},{"id":"D","text":"Nhấn mạnh rằng đầu tư ở ngân hàng khác rủi ro cao hơn và khuyên khách hàng chuyển toàn bộ về đây."}]'::jsonb, 'C', 'Mục tiêu là khai thác insight (điểm hài lòng) để tìm ra khoảng trống hoặc điểm yếu của sản phẩm hiện tại, sau đó giới thiệu lợi thế cạnh tranh riêng của combo (như sự liên kết hệ thống).'),
('3.5', 5, 'Khách hàng thắc mắc: ''Sao không thấy rẻ hơn tự mua lẻ từng sản phẩm?''. Phương án xử lý chính xác nhất là gì?', '[{"id":"A","text":"Giải thích rằng ngân hàng luôn hỗ trợ giá tốt nhất cho khách hàng thân thiết."},{"id":"B","text":"Đưa ra bảng số liệu cụ thể chứng minh mức tiết kiệm hoặc các ưu đãi độc quyền khi mua combo so với mua lẻ."},{"id":"C","text":"Nói rằng khách hàng chưa nắm rõ cấu trúc giá của các sản phẩm lẻ."},{"id":"D","text":"Đề nghị khách hàng gọi lại sau khi đã suy nghĩ kỹ về giá cả."}]'::jsonb, 'B', 'Đây là objection bank riêng của tình huống, yêu cầu bằng chứng thực tế (số liệu/ưu đãi) để bác bỏ nhận định sai lầm về giá, thay vì chỉ nói chung chung.'),
('4.1', 1, 'Khách hàng trung niên tỏ vẻ nghi ngờ, hỏi: "Sao tôi biết đây không phải chiêu trò lừa đảo mới?" Bạn nên xử lý tình huống này như thế nào theo đúng quy định?', '[{"id":"A","text":"Chứng minh bằng lời nói rằng ngân hàng rất uy tín và khách hoàn toàn yên tâm."},{"id":"B","text":"Giải thích chi tiết về công nghệ bảo mật của app để thuyết phục khách."},{"id":"C","text":"Không tranh cãi, mời khách tự kiểm tra thông tin qua tổng đài chính thức hoặc website ngân hàng để xác minh độc lập."},{"id":"D","text":"Khuyên khách ra quầy giao dịch để làm thủ tục an toàn hơn."}]'::jsonb, 'C', 'Với khách đa nghi, việc không tranh cãi mà hướng dẫn khách tự kiểm tra nguồn thông tin chính thức giúp xây dựng niềm tin thực sự.'),
('4.1', 2, 'Khi khách hàng lo ngại về tính an toàn của việc gửi tiết kiệm online so với gửi tại quầy, bạn cần nhấn mạnh điểm nào sau đây?', '[{"id":"A","text":"Gửi online nhanh hơn nhưng rủi ro cao hơn nếu mất điện thoại."},{"id":"B","text":"Tiền gửi được bảo hiểm theo quy định của Nhà nước và sổ tiết kiệm điện tử có giá trị pháp lý tương đương sổ giấy."},{"id":"C","text":"Ngân hàng sẽ bồi thường toàn bộ nếu xảy ra sự cố kỹ thuật từ phía khách hàng."},{"id":"D","text":"Chỉ những tài khoản VIP mới được bảo hiểm tiền gửi khi gửi online."}]'::jsonb, 'B', 'Đáp án đúng khẳng định sự an toàn tuyệt đối, bảo hiểm tiền gửi theo quy định NHNN và giá trị pháp lý bình đẳng giữa sổ điện tử và giấy.'),
('4.1', 3, 'Khách hàng muốn rút tiền trước hạn nhưng sợ bị mất trắng lãi suất. Câu trả lời chuẩn xác nhất là gì?', '[{"id":"A","text":"Nếu rút trước hạn, khách hàng sẽ không nhận được bất kỳ khoản lãi nào."},{"id":"B","text":"Khách hàng chỉ được hưởng lãi suất 0% cho toàn bộ số tiền rút trước hạn."},{"id":"C","text":"Phần tiền gửi đủ kỳ hạn tối thiểu vẫn được tính lãi không kỳ hạn, không bị mất trắng như cơ chế cũ."},{"id":"D","text":"Ngân hàng sẽ giữ lại 50% lãi suất đã accrue cho phần tiền rút trước hạn."}]'::jsonb, 'C', 'Đây là lợi thế cạnh tranh quan trọng: linh hoạt rút trước hạn mà không phạt nặng hay mất hết lãi như các sản phẩm truyền thống trước đây.'),
('4.1', 4, 'Khách hàng质疑 (nghi ngờ) về mức lãi suất cao hơn tại quầy, cho rằng đó chỉ là quảng cáo. Bạn sẽ phản hồi như thế nào?', '[{"id":"A","text":"Cam kết đây là mức lãi suất tốt nhất thị trường hiện nay."},{"id":"B","text":"Giới thiệu khách hàng sang sản phẩm đầu tư khác có rủi ro thấp hơn."},{"id":"C","text":"Thông báo đây là chính sách chính thức, khách có thể xem trực tiếp bảng lãi suất minh bạch và cập nhật thời gian thực trong app."},{"id":"D","text":"Giải thích rằng lãi suất cao hơn là do ngân hàng đang ưu đãi đặc biệt cho nhân viên gọi điện."}]'::jsonb, 'C', 'Tính minh bạch là chìa khóa: khuyến khích khách tự kiểm tra bảng lãi suất real-time trong app để thấy rõ con số cụ thể.'),
('4.1', 5, 'Khách hàng lớn tuổi than phiền: "Tôi không rành công nghệ, sợ thao tác trên app sai." Bạn sẽ giải quyết vấn đề này bằng cách nào?', '[{"id":"A","text":"Yêu cầu khách mang theo con cháu đến ngân hàng hỗ trợ."},{"id":"B","text":"Nhấn mạnh thao tác chỉ gồm 3 bước đơn giản, có hướng dẫn từng bước trong app và luôn có tổng đài/nhân viên hỗ trợ."},{"id":"C","text":"Khuyên khách dùng máy tính bảng thay vì điện thoại thông minh để dễ nhìn hơn."},{"id":"D","text":"Từ chối tư vấn sản phẩm này cho khách vì yêu cầu kỹ năng sử dụng thiết bị."}]'::jsonb, 'B', 'Giảm bớt rào cản tâm lý bằng cách khẳng định tính đơn giản (3 bước), sự hỗ trợ hướng dẫn sẵn có trong app và đội ngũ nhân sự hỗ trợ.'),
('4.2', 1, 'Khách hàng trung niên của bạn lo lắng rằng thẻ tín dụng dễ dẫn đến nợ nần và không kiểm soát được tài chính. Bạn sẽ giải thích như thế nào để trấn an khách hàng dựa trên tính năng sản phẩm?', '[{"id":"A","text":"Khách hàng nên tự ý thức chi tiêu vì ngân hàng không hỗ trợ theo dõi."},{"id":"B","text":"Thẻ có công cụ theo dõi chi tiêu thời gian thực, cho phép đặt hạn mức cảnh báo và hạn mức được cấp phù hợp thu nhập."},{"id":"C","text":"Ngân hàng sẽ tự động trừ tiền từ tài khoản tiết kiệm để trả nợ thay cho khách hàng."},{"id":"D","text":"Khách hàng cần nộp thêm giấy tờ chứng minh tài sản để giảm thiểu rủi ro."}]'::jsonb, 'B', 'Câu trả lời đúng nhấn mạnh vào các công cụ kiểm soát tài chính (theo dõi thời gian thực, đặt cảnh báo) và nguyên tắc cấp hạn mức dựa trên thu nhập, giúp khách hàng yên tâm về khả năng quản lý chi tiêu.'),
('4.2', 2, 'Khi khách hàng hỏi về phí thường niên, bạn cần truyền tải thông điệp nào là chính xác nhất theo chính sách sản phẩm?', '[{"id":"A","text":"Phí thường niên luôn phải đóng ngay khi mở thẻ và không thể miễn."},{"id":"B","text":"Miễn phí hoàn toàn năm đầu; các năm sau có thể tiếp tục miễn nếu đạt doanh số chi tiêu tối thiểu."},{"id":"C","text":"Chỉ miễn phí năm đầu cho khách hàng mua bảo hiểm nhân thọ kèm theo."},{"id":"D","text":"Phí thường niên chỉ áp dụng cho thẻ quốc tế, không áp dụng cho thẻ nội địa."}]'::jsonb, 'B', 'Chính sách ưu đãi rõ ràng là miễn phí năm đầu và cơ chế miễn phí các năm tiếp theo dựa trên điều kiện doanh số chi tiêu, đây là điểm bán hàng quan trọng để giảm rào cản chi phí.'),
('4.2', 3, 'Nếu khách hàng nói: ''Tôi đã có thẻ tín dụng của ngân hàng khác rồi'', hành vi nào sau đây thể hiện đúng quy trình xử lý phản đối để khai thác nhu cầu?', '[{"id":"A","text":"Kéo dài cuộc gọi và giới thiệu lại đầy đủ tất cả ưu đãi của thẻ mới."},{"id":"B","text":"Chấp nhận phản đối và kết thúc cuộc gọi lịch sự."},{"id":"C","text":"Hỏi khách đang thấy thẻ hiện tại còn thiếu ưu đãi gì, sau đó so sánh điểm khác biệt về hoàn tiền/tích điểm."},{"id":"D","text":"Chê trách thẻ cũ của khách hàng kém hiệu quả để buộc khách chuyển đổi."}]'::jsonb, 'C', 'Chiến lược đúng là khai thác nhu cầu bằng cách tìm ra lỗ hổng của thẻ hiện tại (thiếu ưu đãi gì), sau đó so sánh trực tiếp lợi ích vượt trội của thẻ mới (hoàn tiền/tích điểm) thay vì chỉ liệt kê tính năng.'),
('4.2', 4, 'Để khắc phục sự nghi ngờ của khách hàng về thủ tục rườm rà, bạn cần nhấn mạnh yếu tố nào trong quy trình mở thẻ?', '[{"id":"A","text":"Khách hàng cần đến trực tiếp chi nhánh và chờ duyệt vài ngày làm việc."},{"id":"B","text":"Quy trình hoàn toàn qua app, hồ sơ đơn giản với thời gian duyệt chỉ vài phút."},{"id":"C","text":"Cần có người bảo lãnh hoặc tài sản thế chấp để tăng tốc độ phê duyệt."},{"id":"D","text":"Phải ký hợp đồng giấy và gửi về trụ sở ngân hàng trước khi dùng thẻ."}]'::jsonb, 'B', 'Điểm mạnh của sản phẩm là trải nghiệm số hóa nhanh chóng (qua app, duyệt vài phút), giúp loại bỏ nỗi sợ về thủ tục phức tạp và giấy tờ rườm rà.'),
('4.2', 5, 'Khách hàng đa nghi hỏi: ''Vậy sao ngân hàng không nói rõ từ đầu với người khác?'', câu trả lời chuẩn mực nào sau đây phù hợp với nguyên tắc giao tiếp chuyên nghiệp?', '[{"id":"A","text":"Biện minh rằng các nhân viên trước kia chưa được đào tạo bài bản."},{"id":"B","text":"Đồng ý rằng có sự thiếu sót và xin lỗi khách hàng vì vấn đề này."},{"id":"C","text":"Không biện minh cho ai khác, chỉ cam kết phần tư vấn của mình là minh bạch và tập trung vào lợi ích thực tế."},{"id":"D","text":"Nói rằng khách hàng đang hiểu lầm và cần xem lại điều khoản hợp đồng."}]'::jsonb, 'C', 'Trong tình huống khách hàng nghi ngờ tính minh bạch, nhân viên không nên đổ lỗi hay biện minh cho tổ chức/nhân viên khác, mà cần khẳng định lại cam kết cá nhân về sự minh bạch và tập trung vào giá trị sản phẩm.'),
('4.3', 1, 'Khách hàng đa nghi lo ngại về lãi suất vay tiêu dùng vì nghe nói thường rất cao. Nhân viên nên phản hồi như thế nào để đúng với key selling point và objection bank?', '[{"id":"A","text":"Cam kết mức lãi suất cố định thấp nhất thị trường cho mọi khách hàng mà không cần xem xét hồ sơ."},{"id":"B","text":"Giải thích rằng lãi suất phụ thuộc vào hồ sơ cá nhân nhưng vẫn thấp hơn nhiều so với vay nóng bên ngoài và hoàn toàn minh bạch ngay từ đầu."},{"id":"C","text":"Khuyên khách hàng chỉ vay số tiền nhỏ để giảm bớt gánh nặng lãi suất, bất kể nhu cầu thực tế."},{"id":"D","text":"Bỏ qua câu hỏi này và chuyển sang giới thiệu về thủ tục giải ngân nhanh để tạo ấn tượng tốt."}]'::jsonb, 'B', 'Câu trả lời này trực tiếp giải quyết nỗi sợ lãi suất cao bằng cách so sánh với vay nóng (rủi ro cao) và nhấn mạnh tính minh bạch, phù hợp với đối tượng cần sự tin cậy.'),
('4.3', 2, 'Khi khách hàng bày tỏ lo lắng ''Tôi sợ không trả nợ đúng hạn do thu nhập bấp bênh'', hành động nào sau đây là chính xác nhất theo quy trình xử lý phản đối?', '[{"id":"A","text":"Khuyên khách hàng không nên vay nếu cảm thấy không chắc chắn về tài chính trong tương lai."},{"id":"B","text":"Đề nghị vay thêm tiền mặt để khách hàng có khoản dự phòng lớn hơn cho các chi phí phát sinh."},{"id":"C","text":"Cùng khách hàng tính toán số tiền trả góp phù hợp với thu nhập hiện tại và chọn kỳ hạn để khoản thanh toán hàng tháng thoải mái nhất."},{"id":"D","text":"Yêu cầu khách hàng cung cấp thêm tài sản đảm bảo dù sản phẩm là vay tín chấp để giảm rủi ro."}]'::jsonb, 'C', 'Key selling point nhấn mạnh sự linh hoạt. Việc cùng khách hàng tùy chỉnh kỳ hạn và số tiền trả góp giúp giảm áp lực tài chính, tăng khả năng thành công của giao dịch.'),
('4.3', 3, 'Khách hàng trung niên tỏ ra ngần ngại vì nghĩ thủ tục vay phức tạp và tốn thời gian. Giải pháp nào sau đây khắc phục đúng điểm bán hàng cốt lõi?', '[{"id":"A","text":"Yêu cầu khách hàng đến trực tiếp chi nhánh để nhân viên hỗ trợ điền đầy đủ giấy tờ thủ công."},{"id":"B","text":"Nhấn mạnh rằng hồ sơ đơn giản, xét duyệt hoàn toàn online và có thể giải ngân ngay trong ngày nếu hồ sơ đầy đủ."},{"id":"C","text":"Giới thiệu một gói vay ưu đãi đặc biệt yêu cầu cung cấp nhiều giấy tờ chứng minh thu nhập hơn bình thường."},{"id":"D","text":"Bảo khách hàng rằng thủ tục đã được đơn giản hóa rất nhiều và họ không cần quan tâm đến chi tiết nữa."}]'::jsonb, 'B', 'Một trong những USP chính là ''Hồ sơ đơn giản, xét duyệt online''. Câu trả lời này khẳng định lại lợi thế tốc độ và sự tiện lợi, xóa tan rào cản về thủ tục.'),
('4.3', 4, 'Trong tình huống khách hàng nói ''Tôi cần nghĩ thêm, chưa quyết ngay được'' (tâm lý đa nghi, thận trọng), nhân viên nên ứng xử như thế nào?', '[{"id":"A","text":"Thuyết phục khẩn cấp bằng cách nhấn mạnh ưu đãi giảm lãi suất chỉ áp dụng trong 30 phút nữa."},{"id":"B","text":"Tôn trọng quyết định của khách, không gây áp lực, để lại thông tin liên hệ và mời khách quay lại khi sẵn sàng hoặc giữ hạn mức dự phòng trên app."},{"id":"C","text":"Từ chối làm việc với khách vì họ thiếu quyết đoán và có thể sẽ không ký hợp đồng."},{"id":"D","text":"Gửi email spam liên tục các thông tin khuyến mãi để khách hàng nhớ đến sản phẩm."}]'::jsonb, 'B', 'Đối với khách đa nghi/thận trọng, áp lực mua hàng sẽ phản tác dụng. Chiến lược ''giữ liên hệ + hạn mức dự phòng trên app'' tạo giá trị dài hạn mà không xâm phạm quyền riêng tư.'),
('4.3', 5, 'Để kiểm tra kiến thức cơ bản về sản phẩm Vay tiêu dùng tín chấp, đâu là mô tả ĐÚNG VỀ ĐIỀU KIỆN VÀ TÍNH CHẤT SẢN PHẨM?', '[{"id":"A","text":"Yêu cầu bắt buộc phải có tài sản đảm bảo là nhà đất hoặc xe ô tô để được phê duyệt vay."},{"id":"B","text":"Áp dụng cho người từ 18-65 tuổi, không cần chứng minh thu nhập, chỉ cần CMND."},{"id":"C","text":"Phục vụ nhu cầu tiêu dùng cá nhân, không cần tài sản đảm bảo, yêu cầu chứng minh thu nhập và lịch sử tín dụng tốt."},{"id":"D","text":"Chỉ dành riêng cho khách hàng đang làm việc tại các doanh nghiệp nhà nước với hạn mức vay tối đa 500 triệu."}]'::jsonb, 'C', 'Đây là định nghĩa chính xác nhất: Vay tín chấp (không thế chấp), phục vụ tiêu dùng cá nhân, và yêu cầu cơ bản là chứng minh thu nhập + lịch sử tín dụng tốt.'),
('4.4', 1, 'Khách hàng đa nghi, từng bị lừa hỏi: ''Sao tôi tin lần này khác lần trước?''. Theo hướng dẫn xử lý tình huống đặc thù này, nhân viên nên phản hồi như thế nào?', '[{"id":"A","text":"Cam kết chắc chắn rằng sản phẩm an toàn tuyệt đối và không bao giờ có rủi ro."},{"id":"B","text":"Không cần khách tin ngay, mời khách tự đọc kỹ hợp đồng và tự do hỏi bất kỳ điều khoản nào trước khi quyết định."},{"id":"C","text":"Giải thích rằng các công ty bảo hiểm khác đã vi phạm đạo đức nghề nghiệp, trong khi bên chúng tôi thì không."},{"id":"D","text":"Đề nghị ký hợp đồng nhanh để tránh mất ưu đãi giá sớm, khẳng định đây là cơ hội cuối cùng."}]'::jsonb, 'B', 'Với khách hàng đa nghi, việc ép buộc niềm tin sẽ phản tác dụng. Cách tiếp cận đúng là tôn trọng sự thận trọng của khách bằng cách trao quyền chủ động đọc hợp đồng và đặt câu hỏi.'),
('4.4', 2, 'Khách hàng lo lắng về việc ''từng nghe nhiều người bị tư vấn sai, đóng xong không rút được''. Câu trả lời chuẩn xác nhất theo ngân hàng phản đối là gì?', '[{"id":"A","text":"Sản phẩm chỉ dành cho người giàu, người bình thường khó rút tiền nên anh/chị cân nhắc lại."},{"id":"B","text":"Rất hiểu lo lắng này — chúng ta sẽ cùng đọc kỹ từng điều khoản trước khi ký, và anh/chị có 21 ngày cân nhắc sau khi ký để xem xét lại, hoàn toàn chủ động."},{"id":"C","text":"Việc rút tiền phụ thuộc vào thị trường chứng khoán, nếu thị trường tốt thì mới rút được."},{"id":"D","text":"Anh/chị hãy yên tâm, tất cả nhân viên đều được đào tạo bài bản và không ai dám lừa dối khách hàng."}]'::jsonb, 'B', 'Câu trả lời này trực tiếp giải quyết nỗi lo về tính minh bạch và quyền lợi pháp lý (thời gian cân nhắc 21 ngày), giúp khách hàng cảm thấy an tâm và có quyền kiểm soát.'),
('4.4', 3, 'Khi khách hàng trung niên than phiền: ''Phí đóng hàng năm cao quá, tôi không đủ khả năng'', phương án xử lý nào là chính xác?', '[{"id":"A","text":"Khuyên khách hàng tìm vay thêm tiền vì tương lai dài hạn quan trọng hơn hiện tại."},{"id":"B","text":"Giới thiệu một sản phẩm bảo hiểm nhân thọ thuần túy khác rẻ hơn nhưng không có phần đầu tư."},{"id":"C","text":"Thông báo rằng phí sẽ giảm tự động sau 5 năm đầu tiên mà không cần đăng ký lại."},{"id":"D","text":"Có thể điều chỉnh mức phí phù hợp với thu nhập hiện tại, không nhất thiết phải chọn gói cao nhất ngay từ đầu."}]'::jsonb, 'D', 'Linh hoạt trong mức phí là một điểm bán hàng quan trọng, giúp khách hàng thấy rằng sản phẩm vẫn khả thi ngay cả khi ngân sách hiện tại hạn chế.'),
('4.4', 4, 'Khách hàng trẻ tuổi nói: ''Tôi còn trẻ, chưa cần bảo hiểm''. Lập luận thuyết phục nhất dựa trên key selling points là gì?', '[{"id":"A","text":"Tham gia càng sớm, mức phí càng thấp và thời gian tích lũy càng dài — đây chính là thời điểm tối ưu nhất để bắt đầu."},{"id":"B","text":"Nếu không mua bây giờ, khi lớn lên sẽ không thể mua được nữa do sức khỏe suy giảm."},{"id":"C","text":"Bảo hiểm liên kết đầu tư bắt buộc phải có để hưởng lãi suất ngân hàng cao hơn gửi tiết kiệm."},{"id":"D","text":"Đa số người thành đạt đều mua bảo hiểm khi còn trẻ, anh/chị cũng nên làm theo để không tụt hậu."}]'::jsonb, 'A', 'Nhấn mạnh lợi ích tài chính cụ thể: phí thấp hơn khi tham gia sớm và lợi nhuận kép từ thời gian tích lũy dài hạn là lập luận logic nhất cho khách hàng trẻ.'),
('4.4', 5, 'Khách hàng hỏi: ''Bảo hiểm liên kết đầu tư có rủi ro mất tiền không?''. Câu trả lời chuẩn mực nào dưới đây phản ánh đúng cấu trúc sản phẩm?', '[{"id":"A","text":"Không, vì ngân hàng bảo đảm vốn gốc cho mọi nhà đầu tư."},{"id":"B","text":"Sản phẩm gồm 2 phần rõ ràng: phần bảo vệ cố định và phần đầu tư có nhiều mức rủi ro để lựa chọn — mọi thông tin đều được công khai minh bạch trong hợp đồng và minh họa quyền lợi."},{"id":"C","text":"Rủi ro là có thật nhưng phần trăm rất nhỏ, khách hàng chỉ cần giữ hợp đồng lâu là sẽ có lãi."},{"id":"D","text":"Phần đầu tư không chịu rủi ro vì được quản lý bởi quỹ nhà nước, chỉ phần bảo vệ là có điều kiện."}]'::jsonb, 'B', 'Trả lời trung thực về cơ cấu 2 phần (bảo vệ cố định và đầu tư linh hoạt) và nhấn mạnh tính minh bạch giúp xây dựng niềm tin với khách hàng cẩn trọng.'),
('4.5', 1, 'Khách hàng đa nghi, từng bị lừa hỏi: ''Nãy giờ tin tưởng rồi giờ lại đề xuất thêm nữa à?''. Câu trả lời nào sau đây là phù hợp nhất theo quy trình xử lý tình huống đặc biệt này?', '[{"id":"A","text":"Phê phán khách hàng vì thiếu tin tưởng và giải thích lại lợi ích combo một lần nữa."},{"id":"B","text":"Xin lỗi vì gây cảm giác không tốt, khẳng định đây chỉ là gợi ý và khách hoàn toàn có quyền từ chối."},{"id":"C","text":"Đề nghị chuyển sang gọi điện thoại khác để tránh làm mất thiện cảm."},{"id":"D","text":"Báo rằng đây là chính sách bắt buộc của ngân hàng nên khách phải cân nhắc."}]'::jsonb, 'B', 'Theo bank tình huống, cần xin lỗi nếu khách cảm thấy vậy, khẳng định đây chỉ là gợi ý và nhấn mạnh quyền tự quyết của khách.'),
('4.5', 2, 'Khi khách hàng phản đối: ''Nghe combo là thấy bị ép mua thêm cái không cần'', nhân viên sales cần trả lời chuẩn như thế nào?', '[{"id":"A","text":"Giải thích rằng combo luôn rẻ hơn mua lẻ dù có bỏ bớt phần nào đi nữa."},{"id":"B","text":"Không hề ép buộc — anh/chị hoàn toàn có quyền tuỳ chỉnh, bỏ bớt phần không phù hợp, mình chỉ đề xuất dựa trên đúng nhu cầu đã trao đổi."},{"id":"C","text":"Nhấn mạnh rằng các sản phẩm trong combo đều độc lập và không liên quan gì đến nhau."},{"id":"D","text":"Kêu gọi khách hàng hãy tin tưởng vào chuyên môn tư vấn của nhân viên ngân hàng."}]'::jsonb, 'B', 'Câu trả lời chuẩn xác nhận không ép buộc,强调 quyền tùy chỉnh và việc đề xuất dựa trên nhu cầu thực tế đã trao đổi.'),
('4.5', 3, 'Khách hàng nói: ''Tôi chỉ cần 1 sản phẩm thôi, sao phải mua combo?''. Phương án trả lời nào dưới đây thể hiện đúng Key selling point và cách xử lý?', '[{"id":"A","text":"Combo bắt buộc phải mua trọn gói để được miễn phí tài khoản số."},{"id":"B","text":"Hoàn toàn hiểu — combo không bắt buộc trọn gói, mỗi phần đều là sản phẩm độc lập hữu ích, chỉ là khi kết hợp sẽ tiết kiệm chi phí hơn đáng kể."},{"id":"C","text":"Mua lẻ sẽ tốn nhiều thời gian hơn so với mua combo tích hợp."},{"id":"D","text":"Khách hàng nên mua combo vì đây là sản phẩm bán chéo khó nhất và cần thiết."}]'::jsonb, 'B', 'Trả lời cần xác nhận sự thấu hiểu, nhấn mạnh tính linh hoạt (không bắt buộc trọn gói) và lợi ích tiết kiệm chi phí khi kết hợp.'),
('4.5', 4, 'Đối với khách hàng đã có sản phẩm đầu tư ở nơi khác, câu hỏi nào sau đây là bước khai thác insight đúng chuẩn trước khi chỉ ra điểm khác biệt?', '[{"id":"A","text":"Tại sao anh/chị không chuyển toàn bộ sang đầu tư với chúng tôi ngay bây giờ?"},{"id":"B","text":"Vậy sản phẩm hiện tại anh/chị đang hài lòng nhất ở điểm nào?"},{"id":"C","text":"Sản phẩm của ngân hàng khác thường rủi ro cao hơn sản phẩm của chúng tôi."},{"id":"D","text":"Anh/chị cần xem xét lại quyết định đầu tư vì combo của chúng tôi tốt hơn."}]'::jsonb, 'B', 'Bước đầu tiên là khai thác insight bằng cách hỏi về điểm hài lòng của sản phẩm hiện tại, từ đó mới tìm ra điểm khác biệt/bổ sung.'),
('4.5', 5, 'Khách hàng trung niên tỏ ra e dè: ''Tôi cần thời gian suy nghĩ, việc này lớn quá''. Hành động nào sau đây là phù hợp nhất?', '[{"id":"A","text":"Thúc giục khách hàng đưa ra quyết định ngay vì ưu đãi có hạn."},{"id":"B","text":"Đồng ý và hẹn gặp lại vào tuần sau mà không cung cấp thêm tài liệu nào."},{"id":"C","text":"Hoàn toàn tôn trọng — có thể gửi tài liệu tham khảo chi tiết và hẹn trao đổi lại vào thời điểm anh/chị thuận tiện hơn."},{"id":"D","text":"Chuyển cuộc gọi sang phòng ban hỗ trợ khách hàng để họ xử lý."}]'::jsonb, 'C', 'Cần tôn trọng mong muốn suy nghĩ của khách, đồng thời chủ động cung cấp tài liệu tham khảo và thống nhất thời gian trao đổi lại.'),
('5.1', 1, 'Khi tư vấn khách hàng VIP về sản phẩm Tiết kiệm online, yếu tố nào là Key Selling Point cốt lõi để so sánh với gửi tiết kiệm truyền thống tại quầy?', '[{"id":"A","text":"Lãi suất thấp hơn nhưng được tặng quà giá trị cao"},{"id":"B","text":"Lãi suất ưu đãi cao hơn và thao tác hoàn toàn qua app không cần ra chi nhánh"},{"id":"C","text":"Chỉ áp dụng cho khách hàng mới mở tài khoản lần đầu"},{"id":"D","text":"Bắt buộc phải đến giao dịch viên xác nhận danh tính trước khi gửi"}]'::jsonb, 'B', 'Key selling point chính của sản phẩm là lãi suất ưu đãi hơn so với gửi tại quầy và trải nghiệm không cần ra chi nhánh.'),
('5.1', 2, 'Khách hàng lo ngại về độ an toàn khi gửi tiền online và hỏi: ''Lỡ mất điện thoại hoặc bị hack thì sao?''. Câu trả lời chuẩn xác nhất theo ngân hàng là gì?', '[{"id":"A","text":"Khách hàng nên mua thêm bảo hiểm nhân thọ riêng ngoài ngân hàng"},{"id":"B","text":"Ngân hàng chịu trách nhiệm bồi thường 100% nếu do lỗi hệ thống nhưng không bao gồm mất cắp thiết bị"},{"id":"C","text":"Sổ tiết kiệm điện tử có giá trị pháp lý tương đương sổ giấy, tiền gửi được bảo hiểm theo quy định của NHNN và an toàn như gửi tại quầy"},{"id":"D","text":"Cần cài đặt mật khẩu phức tạp và nếu mất thiết bị sẽ mất luôn số tiền đó"}]'::jsonb, 'C', 'Câu trả lời chuẩn nhấn mạnh tính pháp lý của sổ điện tử và sự bảo hiểm tiền gửi theo quy định Nhà nước, đảm bảo an toàn tương đương gửi tại quầy.'),
('5.1', 3, 'Một khách hàng doanh nhân hỏi: ''Tôi nghe nói lãi suất online chỉ là chiêu trò quảng cáo, thực tế không cao hơn tại quầy. Điều này đúng hay sai?'', cách xử lý phản đối nào sau đây là đúng chuẩn?', '[{"id":"A","text":"Nói rằng mức lãi suất thay đổi liên tục nên khó khẳng định chắc chắn"},{"id":"B","text":"Giải thích rằng đây là chính sách chính thức, minh bạch và khách hàng có thể kiểm chứng trực tiếp bảng lãi suất cập nhật thời gian thực trong app"},{"id":"C","text":"Đồng ý rằng đôi khi có chênh lệch nhỏ nhưng khuyên khách nên gửi tại quầy để yên tâm"},{"id":"D","text":"Hướng dẫn khách gọi tổng đài để nghe báo lãi suất cố định mỗi tháng"}]'::jsonb, 'B', 'Phản đối cần được xử lý bằng sự minh bạch: khẳng định đây là chính thức và hướng dẫn khách tự xem bảng lãi suất cập nhật real-time trên app.'),
('5.1', 4, 'Khách hàng trung niên thành đạt quan tâm đến việc rút tiền trước hạn, hỏi: ''Nếu tôi cần dùng tiền gấp giữa kỳ hạn, liệu tôi có bị mất trắng lãi suất không?''. Câu trả lời nào sau đây là chính xác?', '[{"id":"A","text":"Có, phần lãi suất của toàn bộ kỳ hạn sẽ bị hủy bỏ theo quy định cũ"},{"id":"B","text":"Không, phần tiền gửi đủ kỳ hạn tối thiểu vẫn được tính lãi không kỳ hạn, không bị mất trắng như trước đây"},{"id":"C","text":"Có, trừ khi khách hàng ký thỏa thuận đặc biệt với trưởng phòng kinh doanh"},{"id":"D","text":"Không, nhưng ngân hàng sẽ trừ phí quản lý tài khoản vào số tiền gốc"}]'::jsonb, 'B', 'Ưu điểm linh hoạt của sản phẩm là không mất hết lãi khi rút trước hạn; phần tiền đủ điều kiện vẫn được tính lãi không kỳ hạn.'),
('5.1', 5, 'Khách hàng phàn nàn: ''Thao tác trên app tôi không rành công nghệ, sợ làm sai''. Bạn sẽ giải thích thế nào để loại bỏ rào cản này?', '[{"id":"A","text":"Đề nghị khách hàng nhờ con cháu hoặc người thân hỗ trợ thao giúp hoàn toàn"},{"id":"B","text":"Hướng dẫn khách hàng đến chi nhánh gần nhất để nhân viên nhập liệu thay"},{"id":"C","text":"Giải thích thao tác chỉ gồm 3 bước đơn giản, có hướng dẫn từng bước trong app và luôn sẵn sàng hỗ trợ qua tổng đài/nhân viên"},{"id":"D","text":"Nói rằng nếu không biết sử dụng công nghệ thì nên tìm hiểu lại trước khi tham gia"}]'::jsonb, 'C', 'Xử lý phản đối tập trung vào sự đơn giản (3 bước), hỗ trợ tích hợp trong app và kênh hỗ trợ trực tiếp từ nhân viên/tổng đài.'),
('5.2', 1, 'Khách hàng là doanh nhân thành đạt, lo ngại thẻ tín dụng dễ dẫn đến nợ nần do khó kiểm soát chi tiêu. Bạn sẽ phản hồi như thế nào để giải quyết mối quan tâm này dựa trên tính năng sản phẩm?', '[{"id":"A","text":"Nhấn mạnh rằng lãi suất rất thấp nên không có vấn đề gì lớn nếu trả chậm."},{"id":"B","text":"Giới thiệu app có công cụ theo dõi chi tiêu thời gian thực và khả năng tự đặt hạn mức cảnh báo, đồng thời khẳng định hạn mức được cấp dựa trên thu nhập thực tế."},{"id":"C","text":"Khuyên khách hàng chỉ sử dụng thẻ khi đi du lịch nước ngoài để tránh lạm dụng."},{"id":"D","text":"Bảo đảm với khách hàng rằng nhân viên ngân hàng sẽ giám sát chặt chẽ mọi giao dịch của khách."}]'::jsonb, 'B', 'Câu trả lời đúng tập trung vào các công cụ kiểm soát chủ động (app theo dõi, cảnh báo) và nguyên tắc cấp hạn mức dựa trên thu nhập, giúp khách hàng thấy mình làm chủ tài chính.'),
('5.2', 2, 'Khi tư vấn cho khách VIP về phí thường niên, khách hỏi: ''Phí thường niên có đắt không?''. Câu trả lời chuẩn xác nhất theo quy trình là gì?', '[{"id":"A","text":"Miễn phí hoàn toàn năm đầu, các năm sau có thể tiếp tục miễn nếu đạt doanh số chi tiêu tối thiểu theo chính sách."},{"id":"B","text":"Phí thường niên là 1 triệu đồng/năm nhưng hoàn lại ngay sau lần giao dịch đầu tiên."},{"id":"C","text":"Khách hàng không cần đóng phí thường niên vì đây là đặc quyền dành riêng cho khách VIP."},{"id":"D","text":"Phí thường niên được khấu trừ trực tiếp từ số dư tiết kiệm, không ảnh hưởng đến hạn mức thẻ."}]'::jsonb, 'A', 'Chính sách ưu đãi phí thường niên năm đầu và cơ chế miễn phí các năm sau dựa trên doanh số là điểm bán hàng then chốt để giảm rào cản chi phí ban đầu.'),
('5.2', 3, 'Khách hàng đã sở hữu thẻ tín dụng của một ngân hàng khác và nói: ''Tôi đã có thẻ ngân hàng khác rồi''. Chiến lược khai thác nhu cầu và so sánh phù hợp nhất là gì?', '[{"id":"A","text":"Ngay lập tức so sánh lãi suất thấp hơn của ngân hàng chúng ta để thuyết phục hủy thẻ cũ."},{"id":"B","text":"Đồng ý rằng thẻ cũ cũng tốt và khuyên khách hàng giữ nguyên không cần mở thêm thẻ mới."},{"id":"C","text":"Hỏi xem thẻ hiện tại còn thiếu ưu đãi gì, sau đó so sánh sự chênh lệch về chương trình hoàn tiền/tích điểm phù hợp với thói quen chi tiêu."},{"id":"D","text":"Nhấn mạnh thủ tục mở thẻ mới nhanh chóng hơn để khách hàng bỏ thẻ cũ đi."}]'::jsonb, 'C', 'Thao tác đúng là khéo léo khai thác lỗ hổng của thẻ hiện tại (thiếu ưu đãi) rồi dùng lợi thế cạnh tranh (hoàn tiền/tích điểm) để tạo giá trị gia tăng, thay vì tấn công trực diện.'),
('5.2', 4, 'Khách hàng nghi ngờ về độ phức tạp của thủ tục mở thẻ. Bạn cần truyền tải thông tin nào để xóa tan e ngại này?', '[{"id":"A","text":"Khách hàng cần nộp hồ sơ giấy tại quầy và chờ duyệt trong 3-5 ngày làm việc."},{"id":"B","text":"Quy trình hoàn toàn qua app, hồ sơ đơn giản, thời gian duyệt chỉ vài phút."},{"id":"C","text":"Khách hàng cần gặp trực tiếp quản lý quan hệ để ký kết hợp đồng vay vốn."},{"id":"D","text":"Cần cung cấp sổ hộ khẩu và sao kê lương 6 tháng trước khi nộp hồ sơ online."}]'::jsonb, 'B', 'Điểm khác biệt về trải nghiệm khách hàng nằm ở tính tiện lợi: mở thẻ hoàn toàn kỹ thuật số trên app với tốc độ duyệt nhanh, loại bỏ gánh nặng thủ tục hành chính.'),
('5.2', 5, 'Khách hàng là người sành sỏi nhận xét: ''Đặc quyền này ngân hàng nào chẳng có?''. Để xử lý tình huống này với đối tượng khách hàng khó tính, bạn nên làm gì?', '[{"id":"A","text":"Đồng thuận và chuyển sang nói về lãi suất ưu đãi của ngân hàng."},{"id":"B","text":"Nêu ra những điểm khác biệt cụ thể, thật sự riêng biệt của chương trình hoàn tiền/tích điểm mà không đối thủ đang không cung cấp hoặc chưa tối ưu bằng."},{"id":"C","text":"Lặp lại slogan marketing chung chung về dịch vụ khách hàng đẳng cấp."},{"id":"D","text":"Yêu cầu khách hàng thử nghiệm thẻ trong 1 tháng để cảm nhận sự khác biệt."}]'::jsonb, 'B', 'Với khách hàng am hiểu, câu trả lời chung chung sẽ失效. Cần đi vào chi tiết cụ thể về tính độc đáo (unique selling point) của ưu đãi để chứng minh giá trị vượt trội thực sự.'),
('5.3', 1, 'Khách hàng là doanh nhân thành đạt, nhưng phản đối rằng ''Mức lãi suất hiện tại vẫn chưa đủ tốt'' so với đối thủ. Phương án xử lý nào sau đây là đúng chuẩn theo quy định? A. Immediately hạ lãi suất xuống mức thấp nhất có thể để giữ chân khách. B. Từ chối đàm phán và khẳng định đây là mức giá cố định của ngân hàng. C. Đề xuất điều kiện đổi lại (ví dụ: cam kết giao dịch dài hạn) để tạo dư địa đàm phán, không hạ giá vô điều kiện. D. Giới thiệu thêm các gói bảo hiểm đi kèm để bù đắp sự chênh lệch lãi suất.', '[{"id":"A","text":"Immediately hạ lãi suất xuống mức thấp nhất có thể để giữ chân khách."},{"id":"B","text":"Từ chối đàm phán và khẳng định đây là mức giá cố định của ngân hàng."},{"id":"C","text":"Đề xuất điều kiện đổi lại (ví dụ: cam kết giao dịch dài hạn) để tạo dư địa đàm phán, không hạ giá vô điều kiện."},{"id":"D","text":"Giới thiệu thêm các gói bảo hiểm đi kèm để bù đắp sự chênh lệch lãi suất."}]'::jsonb, 'C', 'Theo objection bank riêng cho tình huống khách VIP/đàm phán cứng, nhân viên cần đề xuất điều kiện đổi lại (như cam kết giao dịch) để có thêm không gian thương lượng, tránh việc hạ giá vô điều kiện làm mất giá trị sản phẩm.'),
('5.3', 2, 'Khi khách hàng hỏi: ''Lãi suất vay tiêu dùng thường cao lắm'', câu trả lời chuẩn xác nhất để trấn an khách là gì? A. Lãi suất của chúng tôi luôn thấp hơn tất cả các ngân hàng khác trên thị trường. B. Mức lãi suất phụ thuộc vào hồ sơ từng người, nhưng vẫn thấp hơn nhiều so với vay nóng bên ngoài và minh bạch ngay từ đầu. C. Chúng tôi chỉ áp dụng lãi suất cố định trong 6 tháng đầu, sau đó sẽ thả nổi. D. Khách hàng cần đến trực tiếp chi nhánh để được nhân viên tính toán cụ thể mới biết chính xác.', '[{"id":"A","text":"Lãi suất của chúng tôi luôn thấp hơn tất cả các ngân hàng khác trên thị trường."},{"id":"B","text":"Mức lãi suất phụ thuộc vào hồ sơ từng người, nhưng vẫn thấp hơn nhiều so với vay nóng bên ngoài và minh bạch ngay từ đầu."},{"id":"C","text":"Chúng tôi chỉ áp dụng lãi suất cố định trong 6 tháng đầu, sau đó sẽ thả nổi."},{"id":"D","text":"Khách hàng cần đến trực tiếp chi nhánh để được nhân viên tính toán cụ thể mới biết chính xác."}]'::jsonb, 'B', 'Câu trả lời chuẩn nhấn mạnh tính cá nhân hóa dựa trên hồ sơ, so sánh ưu thế với vay nóng (thường có rủi ro cao và lãi suất phi lý), và cam kết về tính minh bạch ngay từ đầu.'),
('5.3', 3, 'Đối với khách hàng trung niên, thành đạt lo lắng về khả năng tài chính tương lai, khi họ nói ''Tôi sợ không trả nợ đúng hạn'', bạn nên tư vấn như thế nào? A. Khuyên khách vay số tiền nhỏ nhất có thể để giảm áp lực mỗi tháng. B. Cam kết với khách rằng nếu gặp khó khăn thì ngân hàng sẽ miễn giảm toàn bộ nợ. C. Gợi ý cùng tính toán số tiền trả góp phù hợp với thu nhập hiện tại, chọn kỳ hạn để khoản trả hàng tháng thoải mái nhất. D. Chuyển hướng sang sản phẩm gửi tiết kiệm thay vì vay tiêu dùng.', '[{"id":"A","text":"Khuyên khách vay số tiền nhỏ nhất có thể để giảm áp lực mỗi tháng."},{"id":"B","text":"Cam kết với khách rằng nếu gặp khó khăn thì ngân hàng sẽ miễn giảm toàn bộ nợ."},{"id":"C","text":"Gợi ý cùng tính toán số tiền trả góp phù hợp với thu nhập hiện tại, chọn kỳ hạn để khoản trả hàng tháng thoải mái nhất."},{"id":"D","text":"Chuyển hướng sang sản phẩm gửi tiết kiệm thay vì vay tiêu dùng."}]'::jsonb, 'C', 'Giải pháp chuẩn là hỗ trợ khách hàng chủ động quản lý dòng tiền bằng cách cùng tính toán phương án trả góp phù hợp với thu nhập và chọn kỳ hạn tối ưu để đảm bảo tính bền vững.'),
('5.3', 4, 'Khách hàng tỏ ý do dự với lý do ''Thủ tục vay có phức tạp, mất nhiều thời gian không?''. Điểm bán hàng trọng tâm (Key selling point) nào cần được nhấn mạnh? A. Nhấn mạnh vào lãi suất cạnh tranh nhất thị trường. B. Nhấn mạnh vào việc không cần tài sản đảm bảo. C. Nhấn mạnh vào hồ sơ đơn giản, xét duyệt online và giải ngân ngay trong ngày nếu hồ sơ đầy đủ. D. Nhấn mạnh vào độ tuổi chấp nhận vay lên đến 60 tuổi.', '[{"id":"A","text":"Nhấn mạnh vào lãi suất cạnh tranh nhất thị trường."},{"id":"B","text":"Nhấn mạnh vào việc không cần tài sản đảm bảo."},{"id":"C","text":"Nhấn mạnh vào hồ sơ đơn giản, xét duyệt online và giải ngân ngay trong ngày nếu hồ sơ đầy đủ."},{"id":"D","text":"Nhấn mạnh vào độ tuổi chấp nhận vay lên đến 60 tuổi."}]'::jsonb, 'C', 'Để xóa tan nỗi lo về thủ tục rườm rà, cần tập trung vào lợi ích ''xét duyệt online'', ''hồ sơ đơn giản'' và tốc độ ''giải ngân ngay trong ngày'' – những yếu tố trực tiếp giải quyết mối quan ngại về thời gian.'),
('5.3', 5, 'Khi khách hàng nói ''Tôi chưa có nhu cầu vay ngay bây giờ'', chiến lược giữ chân và phát triển quan hệ nào là đúng chuẩn objection bank? A. Ngừng gọi điện và chuyển sang chăm sóc khách hàng khác. B. Thuyết phục khách vay trước để tích điểm thưởng thành viên. C. Không sao, đề nghị giữ liên hệ và giới thiệu hạn mức vay dự phòng sẵn có, khi nào cần chỉ thao tác trên app. D. Yêu cầu khách cung cấp thông tin tài sản để làm thủ tục trước dù chưa vay.', '[{"id":"A","text":"Ngừng gọi điện và chuyển sang chăm sóc khách hàng khác."},{"id":"B","text":"Thuyết phục khách vay trước để tích điểm thưởng thành viên."},{"id":"C","text":"Không sao, đề nghị giữ liên hệ và giới thiệu hạn mức vay dự phòng sẵn có, khi nào cần chỉ thao tác trên app."},{"id":"D","text":"Yêu cầu khách cung cấp thông tin tài sản để làm thủ tục trước dù chưa vay."}]'::jsonb, 'C', 'Cách xử lý chuẩn là tôn trọng quyết định của khách, nhưng chốt lại bằng việc thiết lập một ''hạn mức dự phòng'' tiện lợi qua app, giúp duy trì kết nối và sẵn sàng phục vụ khi nhu cầu thực tế nảy sinh.'),
('5.4', 1, 'Khách hàng VIP phản đối: ''Tôi là khách VIP nhưng sao mức phí không được giảm thấp hơn để tương xứng?'', bạn sẽ xử lý như thế nào?', '[{"id":"A","text":"Đồng ý giảm phí ngay lập tức để giữ chân khách hàng VIP."},{"id":"B","text":"Giải thích cơ cấu phí dựa trên giá trị của quyền lợi mở rộng, khẳng định rằng phí không thể giảm tuỳ tiện thiếu căn cứ."},{"id":"C","text":"Khuyên khách hàng chuyển sang sản phẩm bảo hiểm nhân thọ thuần túy rẻ hơn."},{"id":"D","text":"Nói rằng đây là chính sách cố định và không thể thay đổi dưới bất kỳ hình thức nào."}]'::jsonb, 'B', 'Với khách hàng khó tính, cần giải thích minh bạch về giá trị quyền lợi đi kèm với chi phí, tránh việc giảm phí tuỳ tiện làm mất uy tín hoặc vi phạm quy định.'),
('5.4', 2, 'Khi khách hàng lo ngại về rủi ro mất vốn, câu trả lời chuẩn xác nhất theo ngân hàng là gì?', '[{"id":"A","text":"Cam kết sản phẩm này an toàn tuyệt đối và không bao giờ bị lỗ."},{"id":"B","text":"Thông báo rằng khách hàng có thể tự do rút tiền anytime mà không bị trừ phí."},{"id":"C","text":"Nhấn mạnh sản phẩm gồm 2 phần rõ ràng (bảo vệ cố định và đầu tư chọn mức rủi ro), mọi thông tin đều công khai minh bạch trong hợp đồng."},{"id":"D","text":"Đề nghị khách hàng bỏ qua phần đầu tư chỉ mua phần bảo vệ để an toàn."}]'::jsonb, 'C', 'Câu trả lời phải trung thực về cấu trúc sản phẩm (có phần đầu tư biến động) nhưng nhấn mạnh sự minh bạch và khả năng lựa chọn mức rủi ro phù hợp.'),
('5.4', 3, 'Khách hàng cho rằng: ''Tôi từng nghe nói đóng xong không rút được, rất sợ bị tư vấn sai.'' Bạn sẽ trấn an khách hàng bằng cách nào?', '[{"id":"A","text":"Lời hứa miệng rằng nhân viên sẽ hỗ trợ rút tiền khi khách cần."},{"id":"B","text":"Giới thiệu các sản phẩm khác có tính thanh khoản cao hơn."},{"id":"C","text":"Chia sẻ kinh nghiệm cá nhân về những khách hàng trước đó đã thành công."},{"id":"D","text":"Khẳng định sẽ cùng đọc kỹ điều khoản trước khi ký và nhắc nhở về quyền lợi cân nhắc/hủy trong 21 ngày đầu sau khi ký."}]'::jsonb, 'D', 'Việc sử dụng ''thời gian cân nhắc 21 ngày'' và cam kết minh bạch thông tin trước khi ký là chìa khóa để xóa tan nỗi lo về tư vấn sai lệch.'),
('5.4', 4, 'Khách hàng than phiền: ''Phí đóng hàng năm cao quá, tôi không đủ khả năng tài chính.'' Giải pháp nào đúng?', '[{"id":"A","text":"Bắt buộc khách hàng phải vay thêm để đóng phí đầy đủ."},{"id":"B","text":"Khuyến khích khách hàng đóng một lần toàn bộ hợp đồng."},{"id":"C","text":"Gợi ý điều chỉnh mức phí phù hợp với thu nhập hiện tại, không bắt buộc chọn gói cao nhất ngay từ đầu."},{"id":"D","text":"Từ chối tư vấn vì khách hàng không đủ điều kiện tài chính."}]'::jsonb, 'C', 'Sản phẩm liên kết có tính linh hoạt, nhân viên cần gợi ý tùy chỉnh mức phí để đảm bảo khách hàng duy trì hợp đồng bền vững theo khả năng thực tế.'),
('5.4', 5, 'Khách hàng trẻ tuổi nói: ''Tôi còn trẻ, chưa cần thiết phải mua bảo hiểm ngay lúc này.'' Lập luận chốt sale nào hiệu quả nhất?', '[{"id":"A","text":"Khẳng định rủi ro sức khỏe có thể xảy ra bất cứ lúc nào dù còn trẻ."},{"id":"B","text":"Nhấn mạnh tham gia càng sớm, phí越低 và thời gian tích lũy dài hạn càng tối ưu cho mục tiêu tài chính tương lai."},{"id":"C","text":"Nói rằng nếu không mua thì sẽ mất cơ hội nhận quà tặng từ ngân hàng."},{"id":"D","text":"Áp lực khách hàng rằng các doanh nhân thành đạt đều đã có bảo hiểm rồi."}]'::jsonb, 'B', 'Đối với người trẻ/thành đạt, lợi ích cốt lõi cần đánh vào là ''lợi nhuận kép'' từ việc đóng phí sớm và thời gian tích lũy dài hạn của sản phẩm liên kết.'),
('5.5', 1, 'Khi tư vấn Combo (Tài khoản số + Bảo hiểm + Đầu tư) cho khách hàng VIP thành đạt, đâu là ưu điểm cốt lõi nhất cần nhấn mạnh để tạo sự khác biệt so với việc mua lẻ từng sản phẩm?', '[{"id":"A","text":"Combo có giá rẻ hơn 50% so với thị trường."},{"id":"B","text":"Giải pháp tài chính toàn diện, tiết kiệm chi phí tổng thể và không bị chắp vá."},{"id":"C","text":"Bảo hiểm đi kèm được bảo lãnh bởi ngân hàng nước ngoài."},{"id":"D","text":"Sản phẩm đầu tư trong combo luôn đảm bảo lãi suất cố định cao."}]'::jsonb, 'B', 'Key selling point quan trọng là tính toàn diện, tích hợp liền mạch giúp tiết kiệm chi phí và tối ưu hóa quản lý tài chính, thay vì chỉ tập trung vào giá rẻ hay cam kết lãi suất cố định.'),
('5.5', 2, 'Khách hàng phàn nàn: "Nghe combo là thấy bị ép mua thêm cái không cần.". Bạn sẽ phản hồi chuẩn xác nhất theo nguyên tắc xử lý phản đối của sản phẩm là gì?', '[{"id":"A","text":"Không hề ép buộc — anh/chị hoàn toàn có quyền tuỳ chỉnh, bỏ bớt phần không phù hợp, mình chỉ đề xuất dựa trên đúng nhu cầu đã trao đổi."},{"id":"B","text":"Combo này đang có chương trình khuyến mãi đặc biệt nên rất tốt cho anh/chị lúc này."},{"id":"C","text":"Nếu anh/chị không mua thì sẽ mất cơ hội hưởng các ưu đãi độc quyền của ngân hàng."},{"id":"D","text":"Thực tế các sản phẩm riêng lẻ đều đắt tiền hơn, mua combo mới là thông minh."}]'::jsonb, 'A', 'Câu trả lời chuẩn nhấn mạnh quyền tự do tuỳ chỉnh của khách hàng và khẳng định tư vấn dựa trên nhu cầu thực tế, loại bỏ cảm giác bị ép buộc.'),
('5.5', 3, 'Đối tượng khách hàng trong tình huống này thường là Doanh nhân/Chuyên gia cấp cao. Trước khi đề xuất Combo, hành động bắt buộc nào sau đây nhân viên phải thực hiện?', '[{"id":"A","text":"Giới thiệu ngay bảng so sánh giá giữa mua lẻ và mua combo."},{"id":"B","text":"Khai thác nhu cầu tổng thể và điều kiện tài chính/thu nhập của khách."},{"id":"C","text":"Yêu cầu khách mở ngay tài khoản số để kích hoạt gói ưu đãi."},{"id":"D","text":"Đề xuất mua gói bảo hiểm trước vì đây là sản phẩm dễ chốt nhất."}]'::jsonb, 'B', 'Đây là sản phẩm bán chéo khó, đòi hỏi phải hiểu rõ nhu cầu tổng thể và điều kiện (số dư/thu nhập cao) của khách hàng VIP trước khi đưa ra đề xuất phù hợp.'),
('5.5', 4, 'Khách nói: "Tôi đã có sản phẩm đầu tư ở nơi khác rồi.". Bước đầu tiên bạn nên làm theo quy trình xử lý phản đối này là gì?', '[{"id":"A","text":"Nhắc lại ngay lợi ích liên kết trực tiếp với tài khoản ngân hàng của khách."},{"id":"B","text":"Hỏi: \"Vậy sản phẩm hiện tại anh/chị đang hài lòng nhất ở điểm nào?\" để khai thác insight."},{"id":"C","text":"Giới thiệu các sản phẩm đầu tư khác của ngân hàng có rủi ro thấp hơn."},{"id":"D","text":"Từ bỏ đề xuất đầu tư và chuyển sang tư vấn gói bảo hiểm đơn thuần."}]'::jsonb, 'B', 'Theo objection bank, bước đầu tiên là đặt câu hỏi khơi gợi để hiểu điểm hài lòng của khách, từ đó mới tìm ra điểm khác biệt hoặc sự bổ sung cần thiết của combo.'),
('5.5', 5, 'Trong tình huống khách hàng cảm thấy đề xuất "giống công thức chung chung", chiến lược xử lý nào là đúng đắn nhất?', '[{"id":"A","text":"Thuyết phục khách rằng đây là giải pháp tiêu chuẩn dành cho tất cả khách VIP."},{"id":"B","text":"Quay lại đào sâu thêm 1 insight cụ thể và điều chỉnh đề xuất ngay tại chỗ."},{"id":"C","text":"Gửi hồ sơ chi tiết về email và hẹn gọi lại sau 1 tuần."},{"id":"D","text":"Giảm nhẹ áp lực bằng cách hứa hẹn tặng thêm quà tặng vật chất."}]'::jsonb, 'B', 'Khi khách nghi ngờ tính cá nhân hóa, nhân viên cần quay lại khai thác insight sâu hơn để tùy biến đề xuất, chứng minh giải pháp này thực sự fit với nhu cầu riêng của họ.')
